package com.rsbingo;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The plugin deliberately does no scoring — the server does that. What it does do
 * is derive display values from the server's numbers, and those are worth pinning:
 * a wrong "% to next tier" is the kind of thing nobody notices until an event is
 * live and a team is arguing about it.
 *
 * Figures below are real ones from event NSM930.
 */
public class BoardLogicTest
{
	private static BoardModels.BoardTile showdownTile(int tier, int maxTier, double score, int threshold)
	{
		final BoardModels.BoardTile t = new BoardModels.BoardTile();
		t.pos = 1;
		t.tier = tier;
		t.maxTier = maxTier;
		t.score = score;
		t.tierThreshold = threshold;
		return t;
	}

	@Test
	public void tierProgressMatchesTheServersTier()
	{
		// pos 1: 3,076,134.4 pts at 1M per tier -> tier 3, 76.9% of the way to T4.
		final BoardModels.BoardTile t = showdownTile(3, 5, 3_076_134.4, 1_000_000);

		assertTrue(t.hasTierProgress());
		assertFalse(t.tierMaxed());
		assertEquals(4_000_000.0, t.nextTierAt(), 0.001);
		assertEquals(76.9, t.pctToNextTier(), 0.05);
	}

	@Test
	public void maxedTileIsFlaggedRatherThanShowingAnUnreachableTarget()
	{
		// pos 6: 6.17M with 5 tiers of 1M all banked. The next threshold would be
		// 6M, which it has passed — so the panel must say MAX, not "102% to T6".
		final BoardModels.BoardTile t = showdownTile(5, 5, 6_165_465.2, 1_000_000);

		assertTrue(t.tierMaxed());
	}

	/**
	 * On a Showdown board {@code done} reports the tile's item checklist, which moves
	 * independently of the tier. Real NSM930 tiles sit on both sides of this: Demonic
	 * is T3 with done=true, while Multi Mayhem is a maxed T5 with done=false. Anything
	 * that treats one as the other mislabels both.
	 */
	@Test
	public void tierCompletionIsIndependentOfItemCompletion()
	{
		final BoardModels.BoardTile demonic = showdownTile(3, 5, 3_055_031, 1_000_000);
		demonic.done = true;
		assertFalse("done items must not imply a maxed tier", demonic.tierMaxed());

		final BoardModels.BoardTile multiMayhem = showdownTile(5, 5, 6_165_465, 1_000_000);
		multiMayhem.done = false;
		assertTrue("a maxed tier must not depend on the item checklist", multiMayhem.tierMaxed());
	}

	@Test
	public void percentIsClampedAndNeverExceedsFull()
	{
		final BoardModels.BoardTile over = showdownTile(2, 5, 9_999_999, 1_000_000);
		assertEquals(100.0, over.pctToNextTier(), 0.001);

		final BoardModels.BoardTile none = showdownTile(0, 5, 0, 1_000_000);
		assertEquals(0.0, none.pctToNextTier(), 0.001);
	}

	@Test
	public void nonShowdownTilesHaveNoTierProgress()
	{
		final BoardModels.BoardTile t = new BoardModels.BoardTile();
		t.done = true;

		assertFalse(t.hasTierProgress());
		assertFalse(t.tierMaxed());
		assertEquals(0.0, t.pctToNextTier(), 0.001);
	}

	/**
	 * A Godsword needs three shards plus any one of five hilts — four things. The
	 * checklist lists eight rows, so summing it reports 1/8 (12.5%) for a tile that
	 * is really 1/4 (25%) done. The server caps a group by its logic and sends the
	 * counts it judged completion on; the panel must use those.
	 */
	@Test
	public void groupedTilesUseTheServersCountsNotTheChecklistLength()
	{
		final BoardModels.BoardTile godsword = new BoardModels.BoardTile();
		for (String shard : new String[]{"Godsword Shard 1", "Godsword Shard 2", "Godsword Shard 3"})
		{
			final BoardModels.TileItem item = new BoardModels.TileItem();
			item.label = shard;
			item.need = 1;
			godsword.items.add(item);
		}
		final BoardModels.TileGroup hilts = new BoardModels.TileGroup();
		hilts.name = "Hilt";
		hilts.logic = "any1";
		for (String hilt : new String[]{"Armadyl", "Bandos", "Saradomin", "Zamorak", "Zaros"})
		{
			final BoardModels.TileGroupItem gi = new BoardModels.TileGroupItem();
			gi.label = hilt;
			gi.approved = "Bandos".equals(hilt);
			hilts.items.add(gi);
		}
		godsword.groups.add(hilts);

		// What summing the checklist would have said, and why it is wrong.
		assertEquals(8, godsword.neededCount());
		assertEquals(1, godsword.approvedCount());

		godsword.collected = 1;
		godsword.required = 4;

		assertTrue(godsword.hasCounts());
		assertEquals("1/4", godsword.progressText());
		assertEquals(25.0, godsword.itemsPercent(), 0.001);
	}

	@Test
	public void tilesFallBackToTheChecklistWhenTheServerSendsNoCounts()
	{
		// An older deployment omits these fields; the panel still has to draw a bar.
		final BoardModels.BoardTile tile = new BoardModels.BoardTile();
		final BoardModels.TileItem item = new BoardModels.TileItem();
		item.label = "Twisted Bow";
		item.need = 4;
		item.approved = 1;
		tile.items.add(item);

		assertFalse(tile.hasCounts());
		assertEquals("1/4", tile.progressText());
		assertEquals(25.0, tile.itemsPercent(), 0.001);
	}

	@Test
	public void completedTilesReadAsFullRegardlessOfCounts()
	{
		final BoardModels.BoardTile tile = new BoardModels.BoardTile();
		tile.done = true;
		assertEquals(100.0, tile.itemsPercent(), 0.001);
	}

	@Test
	public void itemCountsSpanFlatItemsAndGroups()
	{
		final BoardModels.BoardTile t = new BoardModels.BoardTile();

		final BoardModels.TileItem dwh = new BoardModels.TileItem();
		dwh.label = "Dragon Warhammer";
		dwh.need = 2;
		dwh.approved = 1;
		t.items.add(dwh);

		final BoardModels.TileGroup g = new BoardModels.TileGroup();
		g.name = "Barrows";
		final BoardModels.TileGroupItem a = new BoardModels.TileGroupItem();
		a.approved = true;
		final BoardModels.TileGroupItem b = new BoardModels.TileGroupItem();
		b.approved = false;
		g.items.add(a);
		g.items.add(b);
		t.groups.add(g);

		assertEquals(2, t.approvedCount());
		assertEquals(4, t.neededCount());
	}

	@Test
	public void hiddenTilesFallBackToTheirPosition()
	{
		final BoardModels.BoardTile t = new BoardModels.BoardTile();
		t.pos = 7;
		t.title = "";

		assertEquals("Tile 7", t.displayTitle());
	}

	@Test
	public void perEventUploadsResolveFromTheSiteRoot()
	{
		assertEquals("https://rs-bingo.com/events/NSM930/images/x.png",
			TileImageCache.resolve("https://rs-bingo.com", "events/NSM930/images/x.png"));

		// A trailing slash on the configured site URL must not double up.
		assertEquals("https://rs-bingo.com/events/NSM930/images/x.png",
			TileImageCache.resolve("https://rs-bingo.com/", "events/NSM930/images/x.png"));
	}

	/**
	 * Anything that isn't an events/ upload is a shared gallery image living under
	 * images/. Resolving these from the site root instead left most of OFM055's
	 * board blank — every path 404'd.
	 */
	@Test
	public void galleryImagesResolveUnderTheImagesDirectory()
	{
		assertEquals("https://rs-bingo.com/images/OFM055/Champion_s_cape.png",
			TileImageCache.resolve("https://rs-bingo.com", "OFM055/Champion_s_cape.png"));

		assertEquals("https://rs-bingo.com/images/default/raids_fit.png",
			TileImageCache.resolve("https://rs-bingo.com", "default/raids_fit.png"));

		// Filenames really do contain spaces; a raw space is not a valid URL.
		assertEquals("https://rs-bingo.com/images/gallery/Abyssal%20whip.png",
			TileImageCache.resolve("https://rs-bingo.com", "gallery/Abyssal whip.png"));

		assertEquals("https://rs-bingo.com/images/a/b.png",
			TileImageCache.resolve("https://rs-bingo.com", "a\\b.png"));

		// "." and ".." are stripped, not resolved — so a path can never climb out of
		// images/. Matches the site, which filters those segments the same way.
		assertEquals("https://rs-bingo.com/images/a/a/b.png",
			TileImageCache.resolve("https://rs-bingo.com", "./a/../a/b.png"));
	}

	/**
	 * WebP has no reader in the JDK, so those tiles are fetched through the site's
	 * converter instead. The whole path goes in one query value — encoded slashes
	 * included — because it is a parameter, not a path.
	 */
	@Test
	public void webpIsRoutedThroughTheConverter()
	{
		assertEquals("https://rs-bingo.com/plugin_img.php?src=events%2FNSM930%2Fimages%2Fx.webp",
			TileImageCache.resolve("https://rs-bingo.com", "events/NSM930/images/x.webp"));

		assertEquals("https://rs-bingo.com/plugin_img.php?src=images%2Fdefault%2Fraids_fit.webp",
			TileImageCache.resolve("https://rs-bingo.com", "default/raids_fit.webp"));

		// The converter is told the cleaned path, so "." and ".." cannot reach it.
		assertEquals("https://rs-bingo.com/plugin_img.php?src=images%2Fa%2Fa%2Fb.webp",
			TileImageCache.resolve("https://rs-bingo.com", "./a/../a/b.webp"));

		// Case is the file system's business, not ours.
		assertEquals("https://rs-bingo.com/plugin_img.php?src=images%2Fg%2FA.WEBP",
			TileImageCache.resolve("https://rs-bingo.com", "g/A.WEBP"));

		// Formats the client can already decode keep going straight to the file.
		assertEquals("https://rs-bingo.com/images/g/a.png",
			TileImageCache.resolve("https://rs-bingo.com", "g/a.png"));

		// Off-site art is refused outright rather than converted — see
		// absoluteImageReferencesAreRefused().
		assertNull(TileImageCache.resolve("https://rs-bingo.com", "https://i.imgur.com/abc.webp"));
	}

	/**
	 * An organiser can paste an absolute link into the tile editor and the website
	 * renders it, but the plugin must not fetch it: the address arrives in an API
	 * response, and a plugin may only contact addresses that are hardcoded or entered
	 * by the user. Returning null leaves the cell on its colour fill.
	 */
	@Test
	public void absoluteImageReferencesAreRefused()
	{
		assertNull(TileImageCache.resolve("https://rs-bingo.com", "https://i.imgur.com/abc.png"));
		assertNull(TileImageCache.resolve("https://rs-bingo.com", "http://i.imgur.com/abc.png"));

		// Not just http(s): any scheme is a way out of the site.
		assertNull(TileImageCache.resolve("https://rs-bingo.com", "file:///etc/passwd"));
		assertNull(TileImageCache.resolve("https://rs-bingo.com", "//evil.example.com/x.png"));

		assertNull(TileImageCache.resolve("https://rs-bingo.com", ""));
		assertNull(TileImageCache.resolve("https://rs-bingo.com", null));
	}

	@Test
	public void scoresAreCompactedTheWayTheSiteDoes()
	{
		assertEquals("3.1M", Text.compact(3_076_134.4));
		assertEquals("5M", Text.compact(5_006_500));
		assertEquals("4.5K", Text.compact(4_500));
		assertEquals("850", Text.compact(850));
		assertEquals("0", Text.compact(0));
	}

	@Test
	public void progressLinesReadAsGainsOrCounts()
	{
		final BoardModels.ProgressLine kc = new BoardModels.ProgressLine();
		kc.label = "Nex";
		kc.gain = 163;
		kc.unit = "KC";
		assertEquals("+163 KC", kc.gainText());

		final BoardModels.ProgressLine xp = new BoardModels.ProgressLine();
		xp.gain = 259408;
		xp.unit = "XP";
		assertEquals("+259.4K XP", xp.gainText());

		// Drops are a count, not a gain — the site writes them as a multiplier.
		final BoardModels.ProgressLine drop = new BoardModels.ProgressLine();
		drop.gain = 1;
		drop.unit = "item";
		assertEquals("x1", drop.gainText());
	}

	@Test
	public void countdownReadsFromTheEventsOwnTimestamps()
	{
		// NSM930's real window.
		final String start = "2026-07-22T17:00:00.000Z";
		final String end = "2026-08-05T17:00:00.000Z";

		assertEquals("Starts in 2d 3h",
			Text.eventCountdown(start, end, java.time.Instant.parse("2026-07-20T14:00:00Z")));
		assertEquals("Ends in 3d 7h",
			Text.eventCountdown(start, end, java.time.Instant.parse("2026-08-02T10:00:00Z")));
		assertEquals("Ended",
			Text.eventCountdown(start, end, java.time.Instant.parse("2026-08-06T10:00:00Z")));

		// Missing or unparseable dates hide the line rather than claiming "Ended".
		assertNull(Text.eventCountdown(null, null, java.time.Instant.now()));
		assertNull(Text.eventCountdown("", "not a date", java.time.Instant.now()));
	}

	/**
	 * Submissions are only open between the two dates. The server enforces this too,
	 * but the panel must not offer a button that is guaranteed to be refused.
	 */
	@Test
	public void submissionsOnlyOpenInsideTheEventWindow()
	{
		final String start = "2026-07-22T17:00:00.000Z";
		final String end = "2026-08-05T17:00:00.000Z";

		assertFalse("before the start",
			Text.withinEventWindow(start, end, java.time.Instant.parse("2026-07-20T14:00:00Z")));
		assertTrue("during",
			Text.withinEventWindow(start, end, java.time.Instant.parse("2026-08-01T10:00:00Z")));
		assertFalse("after the end",
			Text.withinEventWindow(start, end, java.time.Instant.parse("2026-08-06T10:00:00Z")));

		// An event with no dates set is not thereby closed forever.
		assertTrue(Text.withinEventWindow(null, null, java.time.Instant.now()));
	}

	@Test
	public void closedSubmissionsSayWhichEndTheyAreOn()
	{
		final BoardModels.Board board = new BoardModels.Board();
		board.startDate = "2099-01-01T00:00:00.000Z";
		assertEquals("This event has not started yet.", board.submissionsClosedReason());

		board.startDate = "2020-01-01T00:00:00.000Z";
		board.endDate = "2020-02-01T00:00:00.000Z";
		assertEquals("This event has ended.", board.submissionsClosedReason());

		board.endDate = "2099-02-01T00:00:00.000Z";
		assertNull("open events give no reason", board.submissionsClosedReason());
	}

	@Test
	public void durationsCollapseToTwoUnits()
	{
		assertEquals("2d 14h", Text.duration(((2 * 24) + 14) * 3_600_000L));
		assertEquals("2d", Text.duration(2 * 24 * 3_600_000L));
		assertEquals("3h 20m", Text.duration((3 * 3_600_000L) + (20 * 60_000L)));
		assertEquals("12m", Text.duration(12 * 60_000L));
		assertEquals("<1m", Text.duration(30_000L));
	}

	/**
	 * The stamped frame is the whole point of the plugin's submission flow: it is
	 * what a reviewer looks at. It must come back as a decodable PNG the same size as
	 * the captured frame, never a null that silently drops the evidence.
	 */
	@Test
	public void proofScreenshotsEncodeAsPng() throws Exception
	{
		final java.awt.image.BufferedImage frame =
			new java.awt.image.BufferedImage(765, 503, java.awt.image.BufferedImage.TYPE_INT_RGB);

		final byte[] png = ProofShot.stamp(frame, "Hurt Summer Bingo 2026", "codeword123", "NewrockkuOS", "Twisted Bow");

		assertNotNull("a captured frame must always produce proof bytes", png);
		assertTrue(png.length > 0);

		// PNG magic, so this is a real image and not some other encoding.
		assertEquals((byte) 0x89, png[0]);
		assertEquals('P', png[1]);
		assertEquals('N', png[2]);
		assertEquals('G', png[3]);

		final java.awt.image.BufferedImage decoded =
			javax.imageio.ImageIO.read(new java.io.ByteArrayInputStream(png));
		assertNotNull(decoded);
		assertEquals(765, decoded.getWidth());
		assertEquals(503, decoded.getHeight());
	}

	@Test
	public void proofScreenshotsSurviveAMissingFrame()
	{
		// requestNextFrameListener can hand back nothing if the client is not drawing.
		assertNull(ProofShot.stamp(null, "Hurt Summer Bingo 2026", "codeword123", "NewrockkuOS", "Twisted Bow"));
	}

	@Test
	public void organiserSuppliedTitlesCannotInjectMarkupIntoHtmlTooltips()
	{
		// Tile titles reach the board's tooltips, which really are HTML.
		assertEquals("&lt;b&gt;bold&lt;/b&gt;", Text.escape("<b>bold</b>"));
		assertEquals("Tom &amp; Jerry", Text.escape("Tom & Jerry"));
		assertEquals("", Text.escape(null));
	}
}

package com.rsbingo;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

/**
 * Launches a real client with this plugin side-loaded. `./gradlew run` calls this.
 */
public class RsBingoPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(RsBingoPlugin.class);
		RuneLite.main(args);
	}
}

package com.rsbingo;

import com.google.gson.Gson;
import java.awt.Component;
import java.awt.Container;
import java.awt.Graphics2D;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import java.io.File;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.atomic.AtomicReference;
import javax.imageio.ImageIO;
import javax.swing.JFrame;
import javax.swing.SwingUtilities;
import okhttp3.OkHttpClient;

/**
 * Renders the side panel to PNG files without launching a RuneLite client.
 *
 * `./gradlew run` needs a full client, a login and a few minutes; this draws the
 * real panel — same components, same fonts, same live data — in a couple of
 * seconds, which is what you want when checking a layout change.
 *
 * <pre>
 *   ./gradlew preview -Pevent=NSM930
 *   ./gradlew preview -Pevent=NSM930 -Purl=http://localhost/bingotest -Ptile=5
 *   ./gradlew preview -Pevent=NSM930 -Pimages=false
 * </pre>
 *
 * Writes {@code board.png} and {@code tile.png} to {@code build/preview}.
 */
public class PanelPreview
{
	/** Enough for the board plus a long checklist; trimmed off in the PNG. */
	private static final int HEIGHT = 1000;

	public static void main(String[] args) throws Exception
	{
		final String url = property("rs.url", "https://rs-bingo.com");
		final String event = property("rs.event", "");
		final String team = property("rs.team", "");
		final boolean showImages = !"false".equalsIgnoreCase(property("rs.images", "true"));
		final int tileIndex = Integer.parseInt(property("rs.tile", "0"));
		final File out = new File(property("rs.out", "build/preview"));

		if (event.isEmpty())
		{
			System.err.println("No event code. Pass one: ./gradlew preview -Pevent=NSM930");
			System.exit(2);
		}

		if (!out.isDirectory() && !out.mkdirs())
		{
			System.err.println("Could not create " + out);
			System.exit(1);
		}

		final OkHttpClient http = new OkHttpClient();
		final RsBingoApi api = new RsBingoApi(http, new Gson());
		final TileImageCache images = new TileImageCache(http);

		final RsBingoConfig config = new RsBingoConfig()
		{
			@Override
			public String eventCode()
			{
				return event;
			}

			@Override
			public int refreshSeconds()
			{
				return 0;
			}

			@Override
			public boolean showTileImages()
			{
				return showImages;
			}

			@Override
			public String accountToken()
			{
				return property("rs.token", "");
			}

			@Override
			public String selectedTeam()
			{
				return team;
			}

		};

		// Palette has to be in place before the panel is built: components read Brand
		// at construction time, which is exactly why a live switch rebuilds the panel.
		final String themeKey = property("rs.theme", "");
		if (!themeKey.isEmpty())
		{
			final java.util.concurrent.CountDownLatch got = new java.util.concurrent.CountDownLatch(1);
			api.fetchThemes(url, list ->
			{
				for (BoardModels.Theme t : list.themes)
				{
					if (themeKey.equalsIgnoreCase(t.key))
					{
						Brand.applyPalette(t.vars);
						System.out.println("  theme: " + t.label + " (" + t.vars.get("--accent") + ")");
					}
				}
				got.countDown();
			});
			got.await(10, java.util.concurrent.TimeUnit.SECONDS);
		}

		final RsBingoPanel[] holder = new RsBingoPanel[1];
		// The client always passes RsBingoConfig.SITE_URL here; this harness is the one
		// caller that passes anything else, so a local copy of the site can be rendered.
		SwingUtilities.invokeAndWait(() -> holder[0] = new RsBingoPanel(
			api, images, config, url, () -> { }, t -> { }, t -> { }, e -> { }, onFrame -> { }));
		final RsBingoPanel panel = holder[0];

		// There is no game client here, so the logged-in character has to be supplied
		// for the submit controls to appear at all.
		// Linked-account event list, if a token was supplied.
		final String token = property("rs.token", "");
		if (!token.isEmpty())
		{
			api.fetchMyEvents(url, token,
				list -> {
					panel.setMyEvents(list);
					System.out.println("  linked as " + list.username + ", " + list.events.size() + " events");
				},
				err -> System.out.println("  event list: " + err));
			Thread.sleep(1500);
		}

		final String asPlayer = property("rs.player", "");
		if (!asPlayer.isEmpty())
		{
			panel.setLocalPlayer(asPlayer);
		}

		// The panel needs a realised hierarchy for layout and font metrics to match
		// what the client shows. The window is never made visible.
		final JFrame frame = new JFrame("rs-bingo preview");
		SwingUtilities.invokeAndWait(() ->
		{
			// Undecorated, so the content pane is exactly the frame's width and the
			// panel renders at the 225px the client actually gives it.
			frame.setUndecorated(true);
			frame.getContentPane().add(panel);
			frame.setSize(RsBingoPanel.PANEL_WIDTH, HEIGHT);
			frame.addNotify();
			frame.validate();
		});

		// The panel reports fetch failures through its status line; here they should
		// end the run rather than leave it polling for a board that isn't coming.
		final AtomicReference<String> failure = new AtomicReference<>();
		api.fetchBoard(url, event, null, panel::showEvent, failure::set);

		if (!awaitTiles(panel, failure))
		{
			System.err.println(failure.get() != null
				? ("Could not load " + event + " from " + url + ": " + failure.get())
				: ("No board arrived from " + url + " for event " + event + "."));
			System.exit(1);
		}
		// Artwork lands asynchronously and there is no completion signal; give it a
		// moment to settle before drawing.
		Thread.sleep(showImages ? 2500 : 250);

		write(frame, panel, new File(out, "board.png"));

		final List<TileCell> cells = tileCells(panel);
		if (tileIndex >= 0 && tileIndex < cells.size())
		{
			final TileCell cell = cells.get(tileIndex);
			SwingUtilities.invokeAndWait(() -> cell.dispatchEvent(new MouseEvent(
				cell, MouseEvent.MOUSE_CLICKED, System.currentTimeMillis(), 0, 5, 5, 1, false)));
			// Opening a tile fetches its player breakdown; wait for that round trip
			// rather than screenshotting a half-filled card.
			Thread.sleep(2000);
			write(frame, panel, new File(out, "tile.png"));
		}

		SwingUtilities.invokeAndWait(frame::dispose);
		System.out.println("Wrote " + out.getAbsolutePath());
		System.exit(0);
	}

	/** Depth-first layout: validate() alone stops at containers already marked valid. */
	private static void layout(Component c)
	{
		if (c instanceof Container)
		{
			final Container container = (Container) c;
			container.doLayout();
			for (Component child : container.getComponents())
			{
				layout(child);
			}
		}
	}

	/** Polls for the board to render, rather than guessing at a fixed delay. */
	private static boolean awaitTiles(RsBingoPanel panel, AtomicReference<String> failure) throws Exception
	{
		for (int i = 0; i < 100; i++)
		{
			if (!tileCells(panel).isEmpty())
			{
				return true;
			}
			if (failure.get() != null)
			{
				return false;
			}
			Thread.sleep(100);
		}
		return false;
	}

	private static List<TileCell> tileCells(RsBingoPanel panel)
	{
		final List<TileCell> found = new ArrayList<>();
		collect(panel, found);
		return found;
	}

	private static void collect(Component c, List<TileCell> found)
	{
		if (c instanceof TileCell)
		{
			found.add((TileCell) c);
			return;
		}
		if (c instanceof Container)
		{
			for (Component child : ((Container) c).getComponents())
			{
				collect(child, found);
			}
		}
	}

	private static void write(JFrame frame, RsBingoPanel panel, File file) throws Exception
	{
		// The panel calls revalidate() as content arrives, but that only queues a
		// layout pass — and nothing pumps that queue for a frame that is never shown,
		// so the board's cells would keep zero bounds and paint nothing. Lay it out
		// synchronously instead.
		SwingUtilities.invokeAndWait(() -> layout(frame));

		final BufferedImage img = new BufferedImage(
			Math.max(1, panel.getWidth()), Math.max(1, panel.getHeight()), BufferedImage.TYPE_INT_RGB);

		SwingUtilities.invokeAndWait(() ->
		{
			final Graphics2D g = img.createGraphics();
			try
			{
				panel.printAll(g);
			}
			finally
			{
				g.dispose();
			}
		});

		ImageIO.write(img, "png", file);
		System.out.println("  " + file.getName() + "  " + img.getWidth() + "x" + img.getHeight());
	}

	private static String property(String key, String fallback)
	{
		final String v = System.getProperty(key);
		return (v == null || v.isEmpty()) ? fallback : v;
	}
}

package com.rsbingo;

import com.google.gson.Gson;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Pins the contract with plugin_board.php.
 *
 * The fixture is a real response from event NSM930, trimmed to three tiles. Gson
 * maps this by field name with no annotations, so a rename on the PHP side fails
 * silently at runtime — every field would simply be null and the panel would draw
 * an empty board. This test is what makes that break loudly instead.
 */
public class BoardParsingTest
{
	private static BoardModels.Board sample()
	{
		final InputStream in = BoardParsingTest.class.getResourceAsStream("/board_sample.json");
		assertNotNull("board_sample.json missing from test resources", in);
		return new Gson().fromJson(
			new InputStreamReader(in, StandardCharsets.UTF_8), BoardModels.Board.class);
	}

	@Test
	public void eventAndTeamHeaderParse()
	{
		final BoardModels.Board b = sample();

		assertEquals("NSM930", b.eventId);
		assertEquals("Hurt Summer Bingo 2026", b.name);
		assertEquals("Showdown", b.format);
		assertTrue(b.isShowdown());
		assertEquals(4, b.cols);
		assertEquals(4, b.rows);
		assertEquals("The Dark Knights", b.team);
		assertFalse(b.hiddenTiles);
	}

	@Test
	public void teamsCarryPointsAndPlayers()
	{
		final BoardModels.Board b = sample();

		final BoardModels.TeamSummary top = b.teams.get(0);
		assertEquals("The Dark Knights", top.name);
		assertEquals(3429, top.points);
		assertTrue(top.players.contains("Hurt Dark"));

		// The dropdown renders the summary directly, so toString is load-bearing.
		assertEquals("The Dark Knights", top.toString());
	}

	@Test
	public void tilesCarryEverythingThePanelDraws()
	{
		final BoardModels.Board b = sample();
		final BoardModels.BoardTile first = b.board.get(0);

		assertEquals(1, first.pos);
		assertEquals("Stop all the yelling!", first.title);
		assertEquals("events/NSM930/images/hidyboy.png", first.img);
		assertEquals(10, first.points);
		assertTrue(first.tags.contains("Combat"));

		// The Showdown fields the tier line depends on.
		assertEquals(Integer.valueOf(3), first.tier);
		assertEquals(Integer.valueOf(5), first.maxTier);
		assertTrue(first.hasTierProgress());
		assertEquals(4_000_000.0, first.nextTierAt(), 0.001);
	}

	@Test
	public void pointRatesParseForEveryEarningOnTheTile()
	{
		final BoardModels.BoardTile prisonBreak = sample().board.get(2);

		// Three bosses, one skill, two items — what the site's "Point Rates" lists.
		assertEquals(6, prisonBreak.rates.size());
		assertEquals("Boss: Corrupted Gauntlet", prisonBreak.rates.get(0).label);
		assertEquals("12000 pts/KC", prisonBreak.rates.get(0).rate);
		assertEquals("Skill: Herblore", prisonBreak.rates.get(3).label);
		assertEquals("0.3125 pts/XP", prisonBreak.rates.get(3).rate);
		assertEquals("Dragon Warhammer", prisonBreak.rates.get(4).label);
		assertEquals("450000 pts/item", prisonBreak.rates.get(4).rate);
	}

	@Test
	public void playerProgressParsesAndAddsUp()
	{
		final BoardModels.BoardTile prisonBreak = sample().board.get(2);

		final BoardModels.PlayerProgress top = prisonBreak.players.get(0);
		assertEquals("Tw1st3d1ron", top.name);
		assertEquals(999195.0, top.points, 0.001);
		assertEquals(3, top.lines.size());

		// Each line must sum to the player's total, or the card contradicts itself.
		double sum = 0;
		for (BoardModels.ProgressLine line : top.lines)
		{
			sum += line.points;
		}
		assertEquals(top.points, sum, 0.01);

		final BoardModels.ProgressLine first = top.lines.get(0);
		assertEquals("Corrupted Gauntlet", first.label);
		assertEquals("+70 KC", first.gainText());
		assertEquals(840000.0, first.points, 0.001);
	}

	@Test
	public void playerProgressIsOnlySentForTheRequestedTile()
	{
		final BoardModels.Board b = sample();

		// The fixture asked for tile 3, so only that tile carries a breakdown —
		// this is what keeps a board refresh small.
		assertTrue(b.board.get(2).players.size() > 0);
		assertTrue(b.board.get(0).players.isEmpty());
		assertTrue(b.board.get(1).players.isEmpty());

		// Rates, being small and static, ride along on every tile.
		assertFalse(b.board.get(0).rates.isEmpty());
		assertFalse(b.board.get(1).rates.isEmpty());
	}

	@Test
	public void itemChecklistParsesWithApprovedCounts()
	{
		final BoardModels.Board b = sample();

		// pos 3 is "Prison Break": two items, one of them approved.
		final BoardModels.BoardTile prisonBreak = b.board.get(2);
		assertEquals("Prison Break", prisonBreak.title);
		assertTrue(prisonBreak.done);
		assertEquals(2, prisonBreak.items.size());
		assertEquals("Dragon Warhammer", prisonBreak.items.get(0).label);
		assertEquals(1, prisonBreak.items.get(0).need);
		assertEquals(1, prisonBreak.items.get(0).approved);
		assertEquals(1, prisonBreak.approvedCount());
		assertEquals(2, prisonBreak.neededCount());
	}
}

package com.rsbingo;

/**
 * Formatting shared by the board and the tile view.
 *
 * Tile titles, descriptions and item names are typed by event organisers and get
 * rendered through Swing's HTML labels, so they are escaped in exactly one place
 * rather than in each panel that happens to display them.
 */
final class Text
{
	private Text()
	{
	}

	static String escape(String s)
	{
		if (s == null)
		{
			return "";
		}
		return s.replace("&", "&amp;")
			.replace("<", "&lt;")
			.replace(">", "&gt;")
			.replace("\"", "&quot;")
			.replace("'", "&#39;");
	}

	/**
	 * How long an event has left, from the ISO timestamps the site stores
	 * ({@code 2026-08-05T17:00:00.000Z}). Returns null when the dates are missing or
	 * unparseable, which is the signal to hide the line rather than show "Ended".
	 */
	static String eventCountdown(String startIso, String endIso, java.time.Instant now)
	{
		final java.time.Instant start = parseInstant(startIso);
		final java.time.Instant end = parseInstant(endIso);

		if (start != null && now.isBefore(start))
		{
			return "Starts in " + duration(start.toEpochMilli() - now.toEpochMilli());
		}
		if (end == null)
		{
			return null;
		}
		if (now.isAfter(end))
		{
			return "Ended";
		}
		return "Ends in " + duration(end.toEpochMilli() - now.toEpochMilli());
	}

	/**
	 * Whether now sits inside the event's window. Missing or unparseable dates are
	 * treated as "no limit at that end" — the same reading eventCountdown takes, and
	 * the server enforces the real answer regardless.
	 */
	static boolean withinEventWindow(String startIso, String endIso, java.time.Instant now)
	{
		final java.time.Instant start = parseInstant(startIso);
		if (start != null && now.isBefore(start))
		{
			return false;
		}
		final java.time.Instant end = parseInstant(endIso);
		return end == null || !now.isAfter(end);
	}

	/** True when the event's start is still ahead of us. */
	static boolean startsAfter(String startIso, java.time.Instant now)
	{
		final java.time.Instant start = parseInstant(startIso);
		return start != null && now.isBefore(start);
	}

	/** Two units at most: "2d 14h", "3h 20m", "12m", "<1m". */
	static String duration(long millis)
	{
		if (millis < 60_000)
		{
			return "<1m";
		}

		final long minutes = millis / 60_000;
		final long days = minutes / 1440;
		final long hours = (minutes % 1440) / 60;
		final long mins = minutes % 60;

		if (days > 0)
		{
			return hours > 0 ? (days + "d " + hours + "h") : (days + "d");
		}
		if (hours > 0)
		{
			return mins > 0 ? (hours + "h " + mins + "m") : (hours + "h");
		}
		return mins + "m";
	}

	private static java.time.Instant parseInstant(String iso)
	{
		if (iso == null || iso.trim().isEmpty())
		{
			return null;
		}
		try
		{
			return java.time.Instant.parse(iso.trim());
		}
		catch (java.time.format.DateTimeParseException e)
		{
			return null;
		}
	}

	/**
	 * Compact numbers, matching game.html's modal: 1.2M, 4.5K, 850. Showdown scores
	 * run into the millions and the panel is 225px wide.
	 */
	static String compact(double n)
	{
		final double abs = Math.abs(n);
		if (abs >= 1_000_000)
		{
			return trimZero(n / 1_000_000) + "M";
		}
		if (abs >= 1_000)
		{
			return trimZero(n / 1_000) + "K";
		}
		return String.valueOf(Math.round(n));
	}

	private static String trimZero(double v)
	{
		final String s = String.format("%.1f", v);
		return s.endsWith(".0") ? s.substring(0, s.length() - 2) : s;
	}
}

package com.rsbingo;

import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;
import java.io.UnsupportedEncodingException;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Consumer;
import javax.imageio.ImageIO;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

/**
 * Tile artwork, fetched once and kept.
 *
 * The board re-renders on every refresh and every card switch, so the two things
 * that matter here are that a repaint never triggers a second fetch of the same
 * image, and that a board full of art can't grow without bound. Images are scaled
 * down at decode time — nothing draws them larger than a panel cell — which caps
 * a full 200-entry cache at roughly 7MB rather than the tens of megabytes the
 * originals would take.
 */
@Slf4j
@Singleton
class TileImageCache
{
	/** Nothing is drawn bigger than this, so nothing is kept bigger than this. */
	private static final int MAX_DIM = 96;
	private static final int MAX_ENTRIES = 200;

	/** Access-ordered LRU. Synchronized: fetches complete on OkHttp's threads. */
	private final Map<String, BufferedImage> cache = Collections.synchronizedMap(
		new LinkedHashMap<String, BufferedImage>(32, 0.75f, true)
		{
			@Override
			protected boolean removeEldestEntry(Map.Entry<String, BufferedImage> eldest)
			{
				return size() > MAX_ENTRIES;
			}
		});

	/** In-flight and permanently-failed URLs: both stop repaints re-queueing work. */
	private final Set<String> inFlight = ConcurrentHashMap.newKeySet();
	private final Set<String> failed = ConcurrentHashMap.newKeySet();

	private final OkHttpClient httpClient;

	// Package-private rather than private so PanelPreview can build one directly.
	@Inject
	TileImageCache(OkHttpClient httpClient)
	{
		this.httpClient = httpClient;
	}

	/**
	 * @param onLoad run on the EDT if and when the image is available — immediately
	 *               for a cache hit, later for a fetch, never on failure.
	 */
	void get(String url, Consumer<BufferedImage> onLoad)
	{
		if (url == null || url.isEmpty() || failed.contains(url))
		{
			return;
		}

		final BufferedImage hit = cache.get(url);
		if (hit != null)
		{
			onLoad.accept(hit);
			return;
		}

		// A board of 100 cells paints repeatedly; only the first paint should fetch.
		if (!inFlight.add(url))
		{
			return;
		}

		final HttpUrl parsed = HttpUrl.parse(url);
		if (parsed == null)
		{
			inFlight.remove(url);
			failed.add(url);
			return;
		}

		httpClient.newCall(new Request.Builder().url(parsed).get().build()).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				inFlight.remove(url);
				log.debug("rs-bingo tile image failed: {}", url, e);
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response res = response)
				{
					if (!res.isSuccessful() || res.body() == null)
					{
						// A missing image stays missing; don't ask again.
						failed.add(url);
						return;
					}

					final BufferedImage decoded = decodeScaled(res.body().byteStream());
					if (decoded == null)
					{
						failed.add(url);
						return;
					}

					cache.put(url, decoded);
					SwingUtilities.invokeLater(() -> onLoad.accept(decoded));
				}
				catch (IOException e)
				{
					log.debug("rs-bingo tile image unreadable: {}", url, e);
				}
				finally
				{
					inFlight.remove(url);
				}
			}
		});
	}

	private static BufferedImage decodeScaled(InputStream in) throws IOException
	{
		final BufferedImage src = ImageIO.read(in);
		if (src == null)
		{
			return null;
		}

		final int w = src.getWidth();
		final int h = src.getHeight();
		if (w <= 0 || h <= 0)
		{
			return null;
		}
		if (w <= MAX_DIM && h <= MAX_DIM)
		{
			return src;
		}

		final double scale = Math.min(MAX_DIM / (double) w, MAX_DIM / (double) h);
		final int tw = Math.max(1, (int) Math.round(w * scale));
		final int th = Math.max(1, (int) Math.round(h * scale));

		final BufferedImage out = new BufferedImage(tw, th, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = out.createGraphics();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
			g.setRenderingHint(RenderingHints.KEY_RENDERING, RenderingHints.VALUE_RENDER_QUALITY);
			g.drawImage(src, 0, 0, tw, th, null);
		}
		finally
		{
			g.dispose();
		}
		return out;
	}

	/**
	 * Turns a tile's stored image reference into a URL, following the same rule the
	 * website uses (game.html's {@code safeImgSrc}). There are three shapes and they
	 * are not interchangeable:
	 *
	 * <ul>
	 *   <li>an absolute URL — an organiser pasted a link; <b>refused</b>, see below</li>
	 *   <li>{@code events/<id>/images/x.png} — a per-event upload, already a full
	 *       path from the site root</li>
	 *   <li>anything else ({@code OFM055/x.png}, {@code default/x.png}) — a shared
	 *       gallery image, which lives under {@code images/}</li>
	 * </ul>
	 *
	 * Treating that third case as root-relative is what left most of a board blank:
	 * the paths 404 and the cells fall back to a plain fill.
	 *
	 * WebP is sent the long way round, through the site's converter — see
	 * {@link #CONVERTER}.
	 */
	static String resolve(String baseUrl, String img)
	{
		if (img == null || img.trim().isEmpty())
		{
			return null;
		}

		final String path = img.trim();
		if (path.contains("://") || path.startsWith("//"))
		{
			// An organiser can paste an absolute link into the tile editor, and the
			// website renders it. The plugin will not: this string arrives in an API
			// response, and a plugin may only contact addresses that are hardcoded or
			// entered by the user, never ones a server hands it. The tile keeps its
			// colour fill instead. Anything else here is a path on the site.
			//
			// "//host/x.png" is included: it currently resolves onto our own host
			// rather than off-site, but it is written as an absolute reference and
			// the rule is easier to trust when it has no exceptions.
			return null;
		}

		String base = baseUrl == null ? "" : baseUrl.trim();
		while (base.endsWith("/"))
		{
			base = base.substring(0, base.length() - 1);
		}

		if (path.startsWith("events/"))
		{
			return isWebp(path) ? convert(base, path) : base + "/" + path;
		}

		// Gallery images: the stored reference is relative to images/, and the
		// segments are rebuilt rather than concatenated because the filenames
		// contain spaces and quotes.
		final StringBuilder plain = new StringBuilder("images");
		final StringBuilder encoded = new StringBuilder(base).append("/images");
		for (String segment : path.replace('\\', '/').split("/"))
		{
			if (segment.isEmpty() || ".".equals(segment) || "..".equals(segment))
			{
				continue;
			}
			plain.append('/').append(segment);
			encoded.append('/').append(encodeSegment(segment));
		}

		return isWebp(path) ? convert(base, plain.toString()) : encoded.toString();
	}

	/**
	 * The site endpoint that re-encodes WebP as PNG.
	 *
	 * The JDK has no WebP reader, so those tiles decoded to null and drew as empty
	 * cells. Carrying a Java decoder meant shipping a third-party dependency, which
	 * the Plugin Hub bundles, hash-verifies and explicitly asks submitters to avoid;
	 * converting on the server keeps this plugin dependency-free. If the site cannot
	 * convert either, it returns the original and the tile is blank as it was before.
	 */
	private static final String CONVERTER = "/plugin_img.php?src=";

	private static boolean isWebp(String path)
	{
		return path.length() > 5 && path.regionMatches(true, path.length() - 5, ".webp", 0, 5);
	}

	/** Whole path in one query value, so the slashes are encoded along with it. */
	private static String convert(String base, String sitePath)
	{
		return base + CONVERTER + encodeSegment(sitePath);
	}

	/** Percent-encodes one path segment; gallery filenames contain spaces and quotes. */
	private static String encodeSegment(String segment)
	{
		try
		{
			return URLEncoder.encode(segment, StandardCharsets.UTF_8.name()).replace("+", "%20");
		}
		catch (UnsupportedEncodingException e)
		{
			return segment;
		}
	}
}

package com.rsbingo;

import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import javax.imageio.ImageIO;

/**
 * Turns a captured game frame into the PNG that gets filed as proof.
 *
 * The frame is stamped with the event codeword, the player and the item. The
 * codeword is the point: a reviewer seeing it knows the shot came from the plugin
 * at capture time rather than being an image picked off disk, because only someone
 * holding the event's codeword could have produced it.
 */
final class ProofShot
{
	private static final int MARGIN = 10;
	private static final Color BAR = new Color(0, 0, 0, 190);

	private ProofShot()
	{
	}

	/**
	 * @return PNG bytes, or null if the frame could not be encoded.
	 */
	static byte[] stamp(Image frame, String event, String codeword, String player, String item)
	{
		final BufferedImage img = toBuffered(frame);
		if (img == null)
		{
			return null;
		}

		final Graphics2D g = img.createGraphics();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING,
				RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

			// Three lines: which event this is for, who sent it and what for, then the
			// codeword. A reviewer looking at a folder of screenshots can tell them
			// apart from the first line alone.
			final String title = (event == null || event.trim().isEmpty())
				? "rs-bingo" : event.trim();
			final String who = player + "  -  " + item;
			// An event can still be withholding its codeword. The shot is worth filing
			// either way, so fall back to naming the source rather than stamping
			// "codeword: null" onto a reviewer's evidence.
			final String mark = (codeword == null || codeword.trim().isEmpty())
				? "via rs-bingo RuneLite plugin"
				: ("rs-bingo codeword: " + codeword.trim());

			// Top left: the reviewer's eye lands there first, and it is the one corner
			// the game does not fill with the minimap, inventory or chat.
			final Font heading = new Font(Font.SANS_SERIF, Font.BOLD, 24);
			final Font body = new Font(Font.SANS_SERIF, Font.BOLD, 20);

			g.setFont(heading);
			final int headingHeight = g.getFontMetrics().getHeight();
			final int titleWidth = g.getFontMetrics().stringWidth(title);

			g.setFont(body);
			final int lineHeight = g.getFontMetrics().getHeight();
			final int bodyWidth = Math.max(
				g.getFontMetrics().stringWidth(who),
				g.getFontMetrics().stringWidth(mark));

			final int barHeight = headingHeight + (lineHeight * 2) + MARGIN;

			// A backing bar, so the text stays readable over whatever is on screen.
			final int barWidth = Math.max(titleWidth, bodyWidth) + (MARGIN * 2);
			g.setColor(BAR);
			g.fillRoundRect(MARGIN, MARGIN, Math.min(barWidth, img.getWidth() - (MARGIN * 2)),
				barHeight, 10, 10);

			final int textLeft = MARGIN * 2;
			int baseline = MARGIN + headingHeight;

			g.setFont(heading);
			g.setColor(new Color(0xF0D888));
			g.drawString(title, textLeft, baseline);

			g.setFont(body);
			baseline += lineHeight;
			g.setColor(Color.WHITE);
			g.drawString(who, textLeft, baseline);

			baseline += lineHeight;
			g.setColor(new Color(0xD8A830));
			g.drawString(mark, textLeft, baseline);
		}
		finally
		{
			g.dispose();
		}

		try
		{
			final ByteArrayOutputStream out = new ByteArrayOutputStream();
			ImageIO.write(img, "png", out);
			return out.toByteArray();
		}
		catch (IOException e)
		{
			return null;
		}
	}

	/**
	 * DrawManager hands back an Image, which is usually already a BufferedImage but
	 * isn't guaranteed to be; drawing onto it needs one either way.
	 */
	private static BufferedImage toBuffered(Image frame)
	{
		if (frame == null)
		{
			return null;
		}
		if (frame instanceof BufferedImage)
		{
			return (BufferedImage) frame;
		}

		final int w = frame.getWidth(null);
		final int h = frame.getHeight(null);
		if (w <= 0 || h <= 0)
		{
			return null;
		}

		final BufferedImage copy = new BufferedImage(w, h, BufferedImage.TYPE_INT_RGB);
		final Graphics2D g = copy.createGraphics();
		try
		{
			g.drawImage(frame, 0, 0, null);
		}
		finally
		{
			g.dispose();
		}
		return copy;
	}
}

package com.rsbingo;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import java.io.IOException;
import java.net.ConnectException;
import java.net.UnknownHostException;
import java.net.SocketTimeoutException;
import javax.net.ssl.SSLException;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.MultipartBody;
import okhttp3.OkHttpClient;
import okhttp3.RequestBody;
import okhttp3.Request;
import okhttp3.Response;

/**
 * Fetches board state. Read-only: nothing here writes to the event, and no
 * credentials are sent — the event code alone is what grants a view, exactly as it
 * does for the website's board pages.
 */
@Slf4j
@Singleton
public class RsBingoApi
{
	private final OkHttpClient httpClient;
	private final Gson gson;

	// Package-private rather than private so PanelPreview can build one directly.
	@Inject
	RsBingoApi(OkHttpClient httpClient, Gson gson)
	{
		this.httpClient = httpClient;
		this.gson = gson;
	}

	public void fetchBoard(String baseUrl, String eventCode, String team,
						   Consumer<BoardModels.Board> onOk, Consumer<String> onError)
	{
		fetchBoard(baseUrl, eventCode, team, 0, onOk, onError);
	}

	/**
	 * @param team    null or empty for the event summary and team list only.
	 * @param tilePos board position whose player breakdown is wanted, or 0 for none.
	 *                Asking for it here rather than in a second call keeps a refresh
	 *                to one request whether or not a tile is open.
	 * @param onOk    called off the EDT — callers must marshal to Swing themselves.
	 */
	public void fetchBoard(String baseUrl, String eventCode, String team, int tilePos,
						   Consumer<BoardModels.Board> onOk, Consumer<String> onError)
	{
		final HttpUrl parsed = HttpUrl.parse(trimTrailingSlash(baseUrl) + "/plugin_board.php");
		if (parsed == null)
		{
			onError.accept("That site URL doesn't look right.");
			return;
		}

		final HttpUrl.Builder url = parsed.newBuilder().addQueryParameter("eventId", eventCode);
		if (team != null && !team.isEmpty())
		{
			url.addQueryParameter("team", team);
		}
		if (tilePos > 0)
		{
			url.addQueryParameter("tile", Integer.toString(tilePos));
		}

		final Request request = new Request.Builder().url(url.build()).get().build();

		httpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("rs-bingo board fetch failed", e);
				onError.accept(describe(e));
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response res = response)
				{
					final String body = res.body() == null ? "" : res.body().string();

					if (!res.isSuccessful())
					{
						// The endpoint reports its own reasons; surface them rather
						// than a bare status code.
						onError.accept(messageFor(res.code(), body));
						return;
					}

					final BoardModels.Board board = gson.fromJson(body, BoardModels.Board.class);
					if (board == null || board.eventId == null)
					{
						onError.accept("Unexpected response from the site.");
						return;
					}
					onOk.accept(board);
				}
				catch (JsonSyntaxException e)
				{
					onError.accept("Could not read the site's response.");
				}
				catch (IOException e)
				{
					onError.accept("Connection dropped while loading.");
				}
			}
		});
	}

	/**
	 * The site's colour themes. Failure is not surfaced to the user: the panel keeps
	 * the palette it ships with, which is the site's default anyway.
	 */
	public void fetchThemes(String baseUrl, Consumer<BoardModels.ThemeList> onOk)
	{
		final HttpUrl url = HttpUrl.parse(trimTrailingSlash(baseUrl) + "/plugin_themes.php");
		if (url == null)
		{
			return;
		}

		httpClient.newCall(new Request.Builder().url(url).get().build()).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("rs-bingo theme fetch failed", e);
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response res = response)
				{
					if (!res.isSuccessful() || res.body() == null)
					{
						return;
					}
					final BoardModels.ThemeList list =
						gson.fromJson(res.body().string(), BoardModels.ThemeList.class);
					if (list != null && !list.themes.isEmpty())
					{
						onOk.accept(list);
					}
				}
				catch (JsonSyntaxException | IOException e)
				{
					log.debug("rs-bingo theme response unreadable", e);
				}
			}
		});
	}

	/**
	 * The events a linked account belongs to.
	 *
	 * The token goes in a header rather than the query string so it stays out of
	 * server access logs and proxy caches.
	 */
	public void fetchMyEvents(String baseUrl, String token,
							  Consumer<BoardModels.EventList> onOk, Consumer<String> onError)
	{
		final HttpUrl url = HttpUrl.parse(trimTrailingSlash(baseUrl) + "/plugin_events.php");
		if (url == null || token == null || token.trim().isEmpty())
		{
			return;
		}

		final Request request = new Request.Builder()
			.url(url)
			.header("X-Bingo-Token", token.trim())
			.get()
			.build();

		httpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("rs-bingo event list failed", e);
				onError.accept(describe(e));
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response res = response)
				{
					final String body = res.body() == null ? "" : res.body().string();
					if (!res.isSuccessful())
					{
						onError.accept(messageFor(res.code(), body));
						return;
					}
					final BoardModels.EventList list = gson.fromJson(body, BoardModels.EventList.class);
					if (list != null)
					{
						onOk.accept(list);
					}
				}
				catch (JsonSyntaxException e)
				{
					onError.accept("Could not read the site's response.");
				}
				catch (IOException e)
				{
					onError.accept("Connection dropped while loading events.");
				}
			}
		});
	}

	/**
	 * File a submission. The plugin's only write.
	 *
	 * Authorised by roster membership: the server checks the named player is on the
	 * named team of this event. No codeword or session is sent — see the note at the
	 * top of submit_item.php. Everything files as pending, so this cannot score
	 * anything on its own.
	 */
	public void submitItem(String baseUrl, String eventId, String team,
						   String player, int tilePos, int tileRefId, BoardModels.SubmitOption option,
						   byte[] png, Runnable onOk, Consumer<String> onError)
	{
		final HttpUrl url = HttpUrl.parse(trimTrailingSlash(baseUrl) + "/submit_item.php");
		if (url == null)
		{
			onError.accept("That site URL doesn't look right.");
			return;
		}

		// Matches what game.html posts, indices included, so a plugin submission is
		// indistinguishable from a website one once it lands.
		final String itemData = gson.toJson(new SubmissionItem(option));

		final RequestBody body = new MultipartBody.Builder()
			.setType(MultipartBody.FORM)
			.addFormDataPart("eventId", eventId)
			// Routing, not a credential: it tells the endpoint this is a client
			// submission with no browser session to present.
			.addFormDataPart("source", "plugin")
			.addFormDataPart("team", team)
			.addFormDataPart("player", player)
			.addFormDataPart("tileId", Integer.toString(tilePos))
			.addFormDataPart("tileRefId", Integer.toString(tileRefId))
			.addFormDataPart("itemData", itemData)
			.addFormDataPart("image", "proof.png",
				RequestBody.create(MediaType.parse("image/png"), png))
			.build();

		httpClient.newCall(new Request.Builder().url(url).post(body).build()).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("rs-bingo submission failed", e);
				onError.accept(describe(e));
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response res = response)
				{
					final String text = res.body() == null ? "" : res.body().string();
					final SubmitResult result = gson.fromJson(text, SubmitResult.class);

					if (res.isSuccessful() && result != null && result.success)
					{
						onOk.run();
						return;
					}

					// The endpoint explains itself (wrong codeword, not on the team,
					// event not started); pass that through rather than a status code.
					String message = result == null ? null : (result.message != null ? result.message : result.error);
					if (message == null || message.isEmpty())
					{
						message = "Submission failed (" + res.code() + ").";
					}
					onError.accept(message);
				}
				catch (JsonSyntaxException e)
				{
					onError.accept("Could not read the site's response.");
				}
				catch (IOException e)
				{
					onError.accept("Connection dropped while submitting.");
				}
			}
		});
	}

	/** The itemData payload, shaped exactly as game.html's submission builds it. */
	private static class SubmissionItem
	{
		final String label;
		final int index;
		final String type;
		final int groupIndex;
		final int groupItemIndex;

		SubmissionItem(BoardModels.SubmitOption option)
		{
			this.label = option.label;
			this.index = option.index;
			this.type = option.type;
			this.groupIndex = option.groupIndex;
			this.groupItemIndex = option.itemIndex;
		}
	}

	private static class SubmitResult
	{
		boolean success;
		String message;
		String error;
	}

	/**
	 * Turn a transport failure into something a player can act on.
	 *
	 * Every one of these used to read "Could not reach the site", which is true but
	 * useless: a machine that cannot resolve the name, one behind a captive portal
	 * and one with a broken clock rejecting the certificate all looked identical,
	 * and the only way to tell them apart was to reproduce it yourself.
	 */
	private static String describe(IOException e)
	{
		final String host = HttpUrl.parse(RsBingoConfig.SITE_URL) != null
			? HttpUrl.parse(RsBingoConfig.SITE_URL).host()
			: RsBingoConfig.SITE_URL;

		if (e instanceof UnknownHostException)
		{
			return "Can't find " + host + ". Check your internet connection or DNS.";
		}
		if (e instanceof SocketTimeoutException)
		{
			return host + " timed out. It may be down, or your connection is blocking it.";
		}
		if (e instanceof SSLException)
		{
			return "Secure connection to " + host + " failed. Check your system clock, "
				+ "or whether a firewall or VPN is inspecting traffic.";
		}
		if (e instanceof ConnectException)
		{
			return "Connection to " + host + " was refused.";
		}
		return "Could not reach " + host + ".";
	}

	private String messageFor(int code, String body)
	{
		try
		{
			final ApiError err = gson.fromJson(body, ApiError.class);
			if (err != null && err.error != null && !err.error.isEmpty())
			{
				return err.error;
			}
		}
		catch (JsonSyntaxException ignored)
		{
			// fall through to the generic wording
		}

		if (code == 401)
		{
			return "Account token not accepted - re-link from the site.";
		}
		if (code == 404)
		{
			return "No event with that code.";
		}
		if (code == 429)
		{
			return "Too many requests - try again shortly.";
		}
		return "Site returned an error (" + code + ").";
	}

	private static String trimTrailingSlash(String s)
	{
		final String v = s == null ? "" : s.trim();
		return v.endsWith("/") ? v.substring(0, v.length() - 1) : v;
	}

	private static class ApiError
	{
		String error;
	}
}

package com.rsbingo;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(RsBingoConfig.GROUP)
public interface RsBingoConfig extends Config
{
	String GROUP = "rsbingo";

	/**
	 * The one address this plugin ever contacts. Deliberately a constant and not a
	 * setting: a plugin may only talk to addresses that are hardcoded or typed by
	 * the user, so there is nothing here for a config value — or a server response —
	 * to redirect.
	 */
	String SITE_URL = "https://rs-bingo.com";

	@ConfigItem(
		keyName = "eventCode",
		name = "Event code",
		description = "The event ID from the organiser, e.g. NSM930. Leave blank to hide the board.",
		position = 1
	)
	default String eventCode()
	{
		return "";
	}

	@ConfigItem(
		keyName = "refreshSeconds",
		name = "Refresh (seconds)",
		description = "How often to re-fetch the board. 0 disables automatic refresh.",
		position = 3
	)
	default int refreshSeconds()
	{
		return 60;
	}

	/**
	 * Links this client to a site account so the panel can list the events you are
	 * in. Minted at /plugin_link.php while signed in with Discord.
	 *
	 * Read-only and narrowly scoped by design: it lists your events and nothing
	 * else. Optional — the plugin works without it, given an event code.
	 */
	@ConfigItem(
		keyName = "accountToken",
		name = "Account token",
		description = "Paste from the site's Link RuneLite plugin page to list your events. "
			+ "Optional; leave blank and enter event codes by hand.",
		secret = true,
		position = 1
	)
	default String accountToken()
	{
		return "";
	}

	@ConfigItem(
		keyName = "showTileImages",
		name = "Show tile images",
		description = "Draw each tile's artwork. Turn off to save bandwidth - a board's "
			+ "art can run to several MB the first time it loads.",
		position = 4
	)
	default boolean showTileImages()
	{
		return true;
	}

	/**
	 * Written by the panel's theme dropdown. The list itself comes from the site, so
	 * this is a key rather than an enum — adding a theme to js/themes.js is enough to
	 * make it selectable here, with no plugin change.
	 */
	@ConfigItem(
		keyName = "theme",
		name = "Theme",
		description = "Remembers the colour theme picked in the panel.",
		hidden = true,
		position = 6
	)
	default String theme()
	{
		return "";
	}

	/**
	 * Written by the panel's dropdown, not typed by hand — it exists so reopening
	 * the client returns to the team you were watching rather than whichever one is
	 * top of the table that day.
	 */
	@ConfigItem(
		keyName = "selectedTeam",
		name = "Selected team",
		description = "Remembers the team picked in the panel.",
		hidden = true,
		position = 5
	)
	default String selectedTeam()
	{
		return "";
	}
}

package com.rsbingo;

import java.awt.BorderLayout;
import java.awt.CardLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.awt.Rectangle;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextField;
import javax.swing.Scrollable;
import javax.swing.ScrollPaneConstants;
import javax.swing.SwingUtilities;
import javax.swing.JTextArea;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

/**
 * Side panel: event code, team dropdown, the board grid, and — swapped in over it —
 * a tile's detail view.
 */
class RsBingoPanel extends PluginPanel
{
	private static final String CARD_BOARD = "board";
	private static final String CARD_TILE = "tile";

	private static final int CELL_GAP = 3;
	/** Panel width less this class's insets and the scrollbar. */
	private static final int GRID_WIDTH = PANEL_WIDTH - (Brand.PAD * 2) - Brand.SCROLLBAR;

	private final RsBingoApi api;
	private final RsBingoConfig config;

	/** Hardcoded in the client; see the constructor. */
	private final String siteUrl;
	private final Runnable onEventCodeChanged;
	private final Consumer<String> onTeamSelected;
	private final Consumer<BoardModels.Theme> onThemeSelected;
	private final Consumer<String> onEventSelected;
	private final ScreenshotSource screenshots;

	/** Grabs the next rendered game frame. Supplied by the plugin, which has DrawManager. */
	interface ScreenshotSource
	{
		void capture(Consumer<java.awt.Image> onFrame);
	}
	private final TileImageCache images;

	private final JComboBox<BoardModels.TeamSummary> teamBox = new JComboBox<>();
	private final JLabel statusLabel = new JLabel();
	/** Wraps rather than clips: event names are organiser-supplied and can be long. */
	private final JTextArea headerLabel = new JTextArea();
	private final JPanel grid = new JPanel();
	private final JLabel countdown = new JLabel();
	/**
	 * Shown next to the event name, but only when the site itself would show it —
	 * plugin_board.php applies event.html's own hide/release rules before sending it,
	 * so an event still withholding its codeword sends nothing and this stays hidden.
	 */
	private final JLabel codewordLabel = new JLabel();

	/**
	 * Everything below is rebuilt by {@link #buildUi()} on a theme change: these
	 * components bake the palette in when they are created, so they are recreated
	 * rather than recoloured. The panel object itself never changes, which is what
	 * keeps the sidebar open.
	 */
	private JLabel standingsHeading;
	private JPanel standings;
	private JLabel rosterHeading;
	private JPanel rosterWell;
	private JPanel roster;
	private JLabel themeHeading;

	/** Populated from the site, so a theme added there needs no plugin change. */
	private final JComboBox<BoardModels.Theme> themeBox = new JComboBox<>();

	/**
	 * The events a linked account belongs to. Hidden entirely until an account token
	 * is set, because without one the plugin has no idea who is playing and the event
	 * code in settings is the only way in.
	 */
	private JLabel eventHeading;
	private final JComboBox<BoardModels.EventSummary> eventBox = new JComboBox<>();

	/**
	 * The logged-in character, once the client reports one. Used to pick the team you
	 * are actually on and to mark you in the roster — the one thing the panel knows
	 * that the website cannot.
	 */
	private String localPlayer;
	private final CardLayout cards = new CardLayout();
	private JPanel deck;
	private TileDetailPanel detail;
	/** Held so opening a tile can rewind it to the top. */
	private JScrollPane detailScroll;

	private BoardModels.Board current;
	/** Guards the team dropdown's listener while we repopulate it. */
	private boolean populating;
	/**
	 * Which tile the detail view is showing, or null when the grid is up. The
	 * refresh timer uses this to redraw an open tile in place instead of throwing
	 * the reader back to the board every minute.
	 */
	private Integer openTilePos;

	/**
	 * @param siteUrl the address every request goes to. Always
	 *                {@link RsBingoConfig#SITE_URL} in the client; a parameter only so
	 *                the preview harness can render against a local copy of the site.
	 */
	RsBingoPanel(RsBingoApi api, TileImageCache images, RsBingoConfig config, String siteUrl,
				 Runnable onEventCodeChanged, Consumer<String> onTeamSelected,
				 Consumer<BoardModels.Theme> onThemeSelected, Consumer<String> onEventSelected,
				 ScreenshotSource screenshots)
	{
		super(false);
		this.api = api;
		this.images = images;
		this.config = config;
		this.siteUrl = siteUrl;
		this.onEventCodeChanged = onEventCodeChanged;
		this.onTeamSelected = onTeamSelected;
		this.onThemeSelected = onThemeSelected;
		this.onEventSelected = onEventSelected;
		this.screenshots = screenshots;

		// Listeners are attached once, here. buildUi() runs again on every theme
		// change and must not add a second copy of any of them.
		teamBox.addActionListener(e ->
		{
			if (populating)
			{
				return;
			}
			final BoardModels.TeamSummary sel = (BoardModels.TeamSummary) teamBox.getSelectedItem();
			if (sel != null && sel.name != null)
			{
				// A deliberate team switch starts at the board, not on whichever tile
				// happened to be open for the previous team.
				openTilePos = null;
				onTeamSelected.accept(sel.name);
				loadTeam(sel.name);
			}
		});

		eventBox.addActionListener(e ->
		{
			if (populating)
			{
				return;
			}
			final BoardModels.EventSummary sel = (BoardModels.EventSummary) eventBox.getSelectedItem();
			if (sel != null && sel.eventId != null && !sel.eventId.equalsIgnoreCase(eventCode()))
			{
				// Switching events invalidates the team saved for the previous one;
				// preferredTeam() falls back to the player's own team or the leader.
				openTilePos = null;
				onEventSelected.accept(sel.eventId);
			}
		});

		themeBox.addActionListener(e ->
		{
			if (populating)
			{
				return;
			}
			final BoardModels.Theme sel = (BoardModels.Theme) themeBox.getSelectedItem();
			if (sel != null && sel.key != null && !sel.key.equals(config.theme()))
			{
				onThemeSelected.accept(sel);
			}
		});

		buildUi();
	}

	/**
	 * Builds the panel's contents from the current palette.
	 *
	 * Called again whenever the theme changes. Swapping the whole panel out from
	 * under the navigation button worked, but collapsed the sidebar every time —
	 * rebuilding in place keeps the button, and the panel, exactly where they are.
	 */
	private void buildUi()
	{
		removeAll();

		setLayout(new BorderLayout());
		setBackground(Brand.BG_TILE);
		setBorder(BorderFactory.createEmptyBorder(6, Brand.PAD, 6, Brand.PAD));

		// ── controls ────────────────────────────────────────────────────────
		final JPanel controls = new JPanel();
		controls.setLayout(new BoxLayout(controls, BoxLayout.Y_AXIS));
		controls.setBackground(Brand.BG_TILE);

		// Your own events first: this is the fastest way in when an account is linked.
		eventHeading = Brand.sectionLabel("Event");
		styleCombo(eventBox);
		final boolean haveEvents = eventBox.getItemCount() > 0;
		eventHeading.setVisible(haveEvents);
		eventBox.setVisible(haveEvents);

		// Theme second: it is the one control that changes everything below it.
		themeHeading = Brand.sectionLabel("Theme");
		styleCombo(themeBox);
		final boolean haveThemes = themeBox.getItemCount() > 0;
		themeHeading.setVisible(haveThemes);
		themeBox.setVisible(haveThemes);

		final JLabel teamLabel = Brand.sectionLabel("Team");
		styleCombo(teamBox);

		headerLabel.setFont(Brand.bold(14f));
		headerLabel.setForeground(Brand.TEXT_BRIGHT);
		headerLabel.setBorder(BorderFactory.createEmptyBorder(12, 0, 0, 0));
		headerLabel.setLineWrap(true);
		headerLabel.setWrapStyleWord(true);
		headerLabel.setEditable(false);
		headerLabel.setFocusable(false);
		headerLabel.setOpaque(false);

		statusLabel.setFont(FontManager.getRunescapeSmallFont());
		statusLabel.setForeground(Brand.TEXT_DIM);
		statusLabel.setBorder(BorderFactory.createEmptyBorder(2, 0, 0, 0));

		countdown.setFont(FontManager.getRunescapeSmallFont());
		countdown.setForeground(Brand.TEXT_MAIN);
		countdown.setBorder(BorderFactory.createEmptyBorder(1, 0, 0, 0));

		codewordLabel.setFont(FontManager.getRunescapeSmallFont());
		codewordLabel.setForeground(Brand.ACCENT);
		codewordLabel.setBorder(BorderFactory.createEmptyBorder(2, 0, 8, 0));

		// BoxLayout lays children out around a shared alignment axis, so a mix of
		// LEFT and the JComponent default (CENTRE) makes it reserve space on both
		// sides and squeeze components. They all have to agree.
		for (JComponent c : new JComponent[]{eventHeading, eventBox, themeHeading, themeBox,
			teamLabel, teamBox, headerLabel, statusLabel, countdown, codewordLabel})
		{
			c.setAlignmentX(LEFT_ALIGNMENT);
			controls.add(c);
		}

		// ── board grid, then what the site shows around it ──────────────────
		grid.setBackground(Brand.BG_TILE);

		standingsHeading = Brand.sectionLabel("Standings");
		standings = Brand.section();
		rosterHeading = Brand.sectionLabel("Team");
		rosterWell = Brand.well();
		roster = Brand.section();
		rosterWell.add(roster);

		final JPanel boardCard = new JPanel();
		boardCard.setLayout(new BoxLayout(boardCard, BoxLayout.Y_AXIS));
		boardCard.setBackground(Brand.BG_TILE);

		for (JComponent c : new JComponent[]{grid, standingsHeading, standings,
			rosterHeading, rosterWell})
		{
			c.setAlignmentX(LEFT_ALIGNMENT);
			boardCard.add(c);
		}

		detail = new TileDetailPanel(images, config, siteUrl, submitter, this::closeTile);
		detailScroll = scrolling(detail);

		deck = new JPanel(cards);
		deck.setBackground(Brand.BG_TILE);
		// Both cards scroll: a 7x7 board and a long item checklist each outrun the
		// panel's height, and PluginPanel(false) provides no scrolling of its own.
		deck.add(scrolling(boardCard), CARD_BOARD);
		deck.add(detailScroll, CARD_TILE);

		add(controls, BorderLayout.NORTH);
		add(deck, BorderLayout.CENTER);

		cards.show(deck, CARD_BOARD);
	}

	/**
	 * Files submissions on behalf of the tile view.
	 *
	 * Gating lives here because this is what knows the roster: the logged-in
	 * character must be on the team currently being viewed. Viewing another team's
	 * board offers no submit controls at all, since a submission is recorded against
	 * a team and filing one for a team you are not on would simply be wrong.
	 */
	private final TileDetailPanel.Submitter submitter = new TileDetailPanel.Submitter()
	{
		@Override
		public String submittingAs()
		{
			if (localPlayer == null || current == null || current.team == null)
			{
				return null;
			}
			final BoardModels.TeamSummary team = teamNamed(current, current.team);
			if (team == null)
			{
				return null;
			}
			for (String player : team.players)
			{
				if (localPlayer.equalsIgnoreCase(player))
				{
					// Return the roster's spelling: submit_item.php matches it exactly.
					return player;
				}
			}
			return null;
		}

		@Override
		public boolean canSubmit()
		{
			// Being on the team is the whole authorisation. The codeword is only
			// stamped onto the screenshot, so a withheld one must not block anyone.
			return submittingAs() != null;
		}

		@Override
		public void submit(BoardModels.BoardTile tile, BoardModels.SubmitOption option,
						   Consumer<String> onStatus)
		{
			final String as = submittingAs();
			if (as == null || current == null)
			{
				onStatus.accept("You are not on this team.");
				return;
			}

			// The frame arrives on the client thread; everything after it is network
			// work, and the status callback has to land back on the EDT.
			screenshots.capture(frame ->
			{
				final byte[] png = ProofShot.stamp(frame, current.name, codeword(), as, option.label);
				if (png == null)
				{
					SwingUtilities.invokeLater(() -> onStatus.accept("Could not capture the screen."));
					return;
				}

				SwingUtilities.invokeLater(() -> onStatus.accept("Uploading…"));
				api.submitItem(siteUrl, current.eventId,
					current.team, as, tile.pos, tile.id, option, png,
					() -> SwingUtilities.invokeLater(() ->
					{
						onStatus.accept("Submitted - awaiting review.");
						// Pull the board back so the item shows its pending "?" at once.
						refreshCurrentTeam();
					}),
					error -> SwingUtilities.invokeLater(() -> onStatus.accept(error)));
			});
		}
	};

	/** The event's codeword, once the site has released it. */
	private String codeword()
	{
		if (current == null || current.codeword == null || current.codeword.trim().isEmpty())
		{
			return null;
		}
		return current.codeword.trim();
	}

	private static void styleCombo(JComboBox<?> box)
	{
		box.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
		box.setBackground(Brand.BG_WELL);
		box.setForeground(Brand.TEXT_BRIGHT);
		box.setFont(FontManager.getRunescapeSmallFont());
	}

	/**
	 * Repaints the panel in the newly applied palette and redraws whatever it was
	 * showing, so a theme change costs no network round trip.
	 */
	void reskin()
	{
		SwingUtilities.invokeLater(() ->
		{
			final BoardModels.Board showing = current;
			buildUi();
			revalidate();
			repaint();

			if (showing != null)
			{
				showBoard(showing);
			}
		});
	}

	private static JScrollPane scrolling(JComponent content)
	{
		final JScrollPane sp = new JScrollPane(new VerticalContent(content),
			ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED,
			ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		sp.setBorder(BorderFactory.createEmptyBorder());
		sp.getViewport().setBackground(Brand.BG_TILE);
		sp.setBackground(Brand.BG_TILE);
		sp.getVerticalScrollBar().setUnitIncrement(16);
		sp.getVerticalScrollBar().setPreferredSize(new Dimension(8, 0));
		return sp;
	}

	/**
	 * Scrolled content that takes the viewport's width instead of its own preferred
	 * width.
	 *
	 * Without this a plain panel keeps whatever width its widest child asked for,
	 * and since there is no horizontal scrollbar the overflow is simply cut off —
	 * tag lists and descriptions lost their right-hand edge mid-word.
	 */
	private static class VerticalContent extends JPanel implements Scrollable
	{
		VerticalContent(JComponent view)
		{
			setLayout(new BorderLayout());
			setBackground(Brand.BG_TILE);
			// NORTH, so content keeps its natural height and scrolls rather than
			// being stretched down the panel.
			add(view, BorderLayout.NORTH);
		}

		@Override
		public Dimension getPreferredScrollableViewportSize()
		{
			return getPreferredSize();
		}

		@Override
		public int getScrollableUnitIncrement(Rectangle visible, int orientation, int direction)
		{
			return 16;
		}

		@Override
		public int getScrollableBlockIncrement(Rectangle visible, int orientation, int direction)
		{
			return visible.height;
		}

		@Override
		public boolean getScrollableTracksViewportWidth()
		{
			return true;
		}

		@Override
		public boolean getScrollableTracksViewportHeight()
		{
			return false;
		}
	}

	/**
	 * The event being viewed. Read from the config rather than a field in the panel:
	 * the code is a setting, not board data, and having it in both places meant the
	 * panel's copy could overwrite one typed into RuneLite's settings.
	 */
	private String eventCode()
	{
		final String code = config.eventCode();
		return code == null ? "" : code.trim().toUpperCase();
	}

	void setStatus(String text)
	{
		SwingUtilities.invokeLater(() -> statusLabel.setText(text == null ? "" : text));
	}

	/** Event summary + team list; selects a team and loads its board. */
	void showEvent(BoardModels.Board board)
	{
		SwingUtilities.invokeLater(() ->
		{
			current = board;
			openTilePos = null;
			headerLabel.setText(board.name == null ? "" : board.name);
			statusLabel.setText(board.teams.size() + (board.teams.size() == 1 ? " team" : " teams"));

			populating = true;
			teamBox.removeAllItems();
			for (BoardModels.TeamSummary t : board.teams)
			{
				teamBox.addItem(t);
			}

			// Prefer the team last viewed, so reopening the client lands where you
			// left off rather than on whoever is top of the table today.
			final BoardModels.TeamSummary preferred = preferredTeam(board);
			if (preferred != null)
			{
				teamBox.setSelectedItem(preferred);
			}
			populating = false;

			buildStandings(board, preferred == null ? null : preferred.name);
			buildRoster(preferred);
			applyCountdown(board);

			grid.removeAll();
			grid.revalidate();
			grid.repaint();
			cards.show(deck, CARD_BOARD);

			if (preferred != null && preferred.name != null)
			{
				loadTeam(preferred.name);
			}
		});
	}

	/** Every team, ranked, with the one being viewed picked out. */
	private void buildStandings(BoardModels.Board board, String viewing)
	{
		standings.removeAll();
		final boolean any = !board.teams.isEmpty();
		standingsHeading.setVisible(any);
		standings.setVisible(any);

		int rank = 0;
		for (BoardModels.TeamSummary team : board.teams)
		{
			rank++;
			final boolean mine = team.name != null && team.name.equalsIgnoreCase(viewing);
			standings.add(Brand.valueRow(
				rank + ". " + (team.name == null ? "" : team.name),
				String.valueOf(team.points),
				mine ? Brand.TEXT_BRIGHT : Brand.TEXT_DIM,
				mine ? Brand.ACCENT : Brand.TEXT_MAIN,
				mine ? Brand.BG_COMPLETED_WELL : Brand.BG_WELL));
			standings.add(Box.createVerticalStrut(2));
		}
	}

	/** Who is on the selected team, with the logged-in character marked. */
	private void buildRoster(BoardModels.TeamSummary team)
	{
		roster.removeAll();
		final boolean any = team != null && !team.players.isEmpty();
		rosterHeading.setVisible(any);
		rosterWell.setVisible(any);

		if (!any)
		{
			return;
		}

		rosterHeading.setText(("Team (" + team.players.size() + ")").toUpperCase());

		for (String player : team.players)
		{
			final boolean isMe = localPlayer != null && localPlayer.equalsIgnoreCase(player);
			final JTextArea row = Brand.wrapping(FontManager.getRunescapeSmallFont(),
				isMe ? Brand.ACCENT : Brand.TEXT_MAIN);
			Brand.setWrapped(row, isMe ? (player + "  (you)") : player);
			row.setBorder(BorderFactory.createEmptyBorder(1, 0, 1, 0));
			roster.add(row);
		}
	}

	private void applyCountdown(BoardModels.Board board)
	{
		final String text = Text.eventCountdown(board.startDate, board.endDate, java.time.Instant.now());
		countdown.setVisible(text != null);
		countdown.setText(text == null ? "" : text);

		final boolean hasCodeword = board.codeword != null && !board.codeword.trim().isEmpty();
		codewordLabel.setVisible(hasCodeword);
		codewordLabel.setText(hasCodeword ? ("Codeword: " + board.codeword.trim()) : "");
	}

	private static BoardModels.TeamSummary teamNamed(BoardModels.Board board, String name)
	{
		for (BoardModels.TeamSummary t : board.teams)
		{
			if (t.name != null && t.name.equalsIgnoreCase(name))
			{
				return t;
			}
		}
		return null;
	}

	/**
	 * Offers the linked account's events in the panel's dropdown, selecting whichever
	 * one is currently loaded. Hidden when the account has no events, rather than
	 * showing an empty control.
	 */
	void setMyEvents(BoardModels.EventList list)
	{
		SwingUtilities.invokeLater(() ->
		{
			populating = true;
			eventBox.removeAllItems();

			final String loaded = eventCode();
			for (BoardModels.EventSummary event : list.events)
			{
				eventBox.addItem(event);
				if (event.eventId != null && event.eventId.equalsIgnoreCase(loaded))
				{
					eventBox.setSelectedItem(event);
				}
			}
			populating = false;

			final boolean any = eventBox.getItemCount() > 0;
			eventHeading.setVisible(any);
			eventBox.setVisible(any);
			revalidate();
			repaint();
		});
	}

	/**
	 * Offers the site's themes in the panel's dropdown, selecting the saved one.
	 * Called once the list arrives; until then the switcher stays hidden rather than
	 * showing an empty control.
	 */
	void setThemes(BoardModels.ThemeList list)
	{
		SwingUtilities.invokeLater(() ->
		{
			populating = true;
			themeBox.removeAllItems();

			final String saved = config.theme() == null || config.theme().isEmpty()
				? list.defaultKey
				: config.theme();

			for (BoardModels.Theme theme : list.themes)
			{
				themeBox.addItem(theme);
				if (theme.key != null && theme.key.equals(saved))
				{
					themeBox.setSelectedItem(theme);
				}
			}
			populating = false;

			final boolean any = themeBox.getItemCount() > 0;
			themeHeading.setVisible(any);
			themeBox.setVisible(any);
		});
	}

	/**
	 * Tells the panel which character is logged in, so it can pick that player's team
	 * and mark them in the roster. Safe to call before a board has loaded.
	 */
	void setLocalPlayer(String name)
	{
		SwingUtilities.invokeLater(() ->
		{
			if (name == null || name.equals(localPlayer))
			{
				return;
			}
			localPlayer = name;

			// Redraw everything this feeds, not just the roster: the name decides
			// whether the open tile offers submit controls, and it usually arrives a
			// tick or two after a board is already on screen. No refetch — this
			// redraws the board already held.
			if (current != null)
			{
				showBoard(current);
			}
		});
	}

	private BoardModels.TeamSummary preferredTeam(BoardModels.Board board)
	{
		if (board.teams.isEmpty())
		{
			return null;
		}

		// An explicit choice wins; it is the one thing the user actually asked for.
		final String saved = config.selectedTeam() == null ? "" : config.selectedTeam().trim();
		if (!saved.isEmpty())
		{
			final BoardModels.TeamSummary chosen = teamNamed(board, saved);
			if (chosen != null)
			{
				return chosen;
			}
		}

		// Otherwise the team the logged-in character is actually on, which is almost
		// always the one they want and saves them hunting through the dropdown.
		if (localPlayer != null)
		{
			for (BoardModels.TeamSummary t : board.teams)
			{
				for (String player : t.players)
				{
					if (localPlayer.equalsIgnoreCase(player))
					{
						return t;
					}
				}
			}
		}

		return board.teams.get(0);
	}

	/** A team's board. */
	void showBoard(BoardModels.Board board)
	{
		SwingUtilities.invokeLater(() ->
		{
			current = board;

			int pts = 0;
			for (BoardModels.TeamSummary t : board.teams)
			{
				if (t.name != null && t.name.equals(board.team))
				{
					pts = t.points;
					break;
				}
			}

			int done = 0;
			int placed = 0;
			for (BoardModels.BoardTile t : board.board)
			{
				if (t.empty)
				{
					continue;
				}
				placed++;
				if (t.done)
				{
					done++;
				}
			}
			statusLabel.setText(pts + " pts  ·  " + done + "/" + placed + " tiles");
			applyCountdown(board);
			buildStandings(board, board.team);
			buildRoster(teamNamed(board, board.team));

			final int cols = Math.max(1, board.cols);
			final int cell = Math.max(24, (GRID_WIDTH - (cols - 1) * CELL_GAP) / cols);

			grid.removeAll();
			grid.setLayout(new GridLayout(0, cols, CELL_GAP, CELL_GAP));
			for (BoardModels.BoardTile tile : board.board)
			{
				grid.add(new TileCell(tile, board, images, config, siteUrl, cell,
					() -> openTile(tile, board)));
			}
			grid.revalidate();
			grid.repaint();

			// A refresh landing while a tile is open should update that tile, not
			// yank the reader back to the grid.
			final BoardModels.BoardTile open = findTile(board, openTilePos);
			if (open != null)
			{
				detail.show(open, board);
			}
			else
			{
				openTilePos = null;
				cards.show(deck, CARD_BOARD);
			}
		});
	}

	private static BoardModels.BoardTile findTile(BoardModels.Board board, Integer pos)
	{
		if (pos == null)
		{
			return null;
		}
		for (BoardModels.BoardTile t : board.board)
		{
			if (t.pos == pos && !t.empty)
			{
				return t;
			}
		}
		return null;
	}

	private void openTile(BoardModels.BoardTile tile, BoardModels.Board board)
	{
		openTilePos = tile.pos;
		detail.show(tile, board);
		cards.show(deck, CARD_TILE);

		// A newly opened tile starts at its title, not wherever the last one was left.
		// Deferred so it runs after the swapped-in card has been laid out.
		SwingUtilities.invokeLater(() -> detailScroll.getVerticalScrollBar().setValue(0));

		// The board fetch carries no per-player breakdown, so ask for this tile's now
		// that it is open. showBoard() redraws the open tile in place when it lands,
		// which is the same path the refresh timer uses.
		if (board.team != null && !tile.rates.isEmpty() && tile.players.isEmpty())
		{
			loadTeam(board.team);
		}
	}

	private void closeTile()
	{
		openTilePos = null;
		cards.show(deck, CARD_BOARD);
	}

	private void loadTeam(String team)
	{
		final String code = eventCode();
		if (code.isEmpty())
		{
			return;
		}
		setStatus("Loading " + team + "…");
		// Ask for the open tile's player breakdown in the same request. The server
		// only sends it for this one tile, which is what keeps the response small.
		api.fetchBoard(siteUrl, code, team, openTilePos == null ? 0 : openTilePos,
			this::showBoard, this::setStatus);
	}

	/** Re-fetch the team currently selected, if any. Used by the refresh timer. */
	void refreshCurrentTeam()
	{
		if (current == null || current.team == null)
		{
			return;
		}
		loadTeam(current.team);
	}

	void clearBoard()
	{
		SwingUtilities.invokeLater(() ->
		{
			current = null;
			openTilePos = null;
			headerLabel.setText("");
			populating = true;
			teamBox.removeAllItems();
			populating = false;
			grid.removeAll();
			grid.revalidate();
			grid.repaint();
			cards.show(deck, CARD_BOARD);
		});
	}
}

package com.rsbingo;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.ImageIcon;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JProgressBar;
import javax.swing.JTextArea;
import javax.swing.SwingConstants;
import javax.swing.JComboBox;
import javax.swing.text.DefaultCaret;
import java.util.function.Consumer;
import net.runelite.client.ui.ColorScheme;
