/**
 * The tile "modal". A RuneLite side panel is ~225px wide, so a floating dialog
 * would be unusable — this is a full-panel view swapped in over the grid with a
 * back button, which is the idiomatic equivalent.
 *
 * It shows what game.html's modal shows: title, artwork, points, a progress bar,
 * the Showdown tier line, the description, and the checklist or breakdowns.
 *
 * The one thing it leaves out is the tag list. Tags name the bosses and skills that
 * Point Rates already lists *with* their values, and on a 225px panel that
 * duplicate ran to several lines.
 *
 * Anything that can wrap is a read-only {@link JTextArea} rather than an HTML
 * {@link JLabel}. Swing's {@code width:Npx} style is a hint, not a constraint — it
 * let long tag lists and descriptions render past the panel and lose their right
 * edge mid-word. A text area wraps to the width it is actually given, and as plain
 * text it also can't be tripped up by markup in an organiser's tile description.
 */
class TileDetailPanel extends JPanel
{
		/** XP figures run to millions; the site groups them and so do we. */
	private static final java.text.NumberFormat THOUSANDS =
		java.text.NumberFormat.getIntegerInstance(java.util.Locale.US);

	private final TileImageCache images;
	private final RsBingoConfig config;
	private final String siteUrl;
	private final Submitter submitter;

	/**
	 * How the tile view files a submission. Implemented by the panel, which knows the
	 * event, the team and the logged-in character.
	 */
	interface Submitter
	{
		/** The character to submit as, or null when they are not on the viewed team. */
		String submittingAs();

		/** False while the event is still withholding the codeword submissions carry. */
		boolean canSubmit();

		void submit(BoardModels.BoardTile tile, BoardModels.SubmitOption option, Consumer<String> onStatus);
	}

	private final JLabel imageLabel = new JLabel();
	private final javax.swing.JTextPane title;
	private final JLabel status = new JLabel();
	private final JLabel meta = new JLabel();
	private final Brand.ProgressBar progress = new Brand.ProgressBar();
	private final JLabel tierLine = new JLabel();
	private final JTextArea description;
	private final JPanel checklist = Brand.section();

	private final JLabel xpTotal = new JLabel();
	private final JLabel xpGoal = new JLabel();
	private final JLabel xpHeading = Brand.sectionLabel("Team XP Breakdown");
	private final JPanel xpPlayers = Brand.section();

	private final JLabel descriptionHeading = Brand.sectionLabel("Description");
	private final JLabel ratesHeading = Brand.sectionLabel("Point Rates");
	private final JPanel rates = Brand.section();
	private final JLabel progressHeading = Brand.sectionLabel("Player Progress");
	private final JPanel playerProgress = Brand.section();
	private final JLabel checklistHeading = Brand.sectionLabel("Checklist");

	private final JLabel submitHeading = Brand.sectionLabel("Submit");
	private final JPanel submitWell = Brand.well();
	private final JComboBox<BoardModels.SubmitOption> submitBox = new JComboBox<>();
	private final JButton submitButton = Brand.button("Take screenshot & submit", Brand.ACCENT);
	private final JLabel submitAs = new JLabel();
	/** Breathing room so the button doesn't sit flush against the picker. */
	private final JPanel submitGap = spacer(6);
	private final JTextArea submitStatus = Brand.wrapping(FontManager.getRunescapeSmallFont(), Brand.TEXT_MAIN);

	/** Wells wrapping the sections above, held so they can be hidden with them. */
	private final JPanel descriptionWell = Brand.well();
	private final JPanel xpWell = Brand.well();
	private final JPanel checklistWell = Brand.well();

	TileDetailPanel(TileImageCache images, RsBingoConfig config, String siteUrl,
					Submitter submitter, Runnable onBack)
	{
		this.images = images;
		this.config = config;
		this.siteUrl = siteUrl;
		this.submitter = submitter;

		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setBackground(Brand.BG_TILE);
		setBorder(BorderFactory.createEmptyBorder(6, Brand.PAD, 10, Brand.PAD));

		// Outlined in the accent rather than the border colour: this is the only way
		// out of a tile, and against BG_WELL a border-coloured outline is nearly the
		// same value as the panel behind it, so the control read as a caption strip
		// rather than something to press.
		final JButton back = Brand.button("< Back to board", Brand.TEXT_BRIGHT);
		back.setFont(Brand.bold(14f));
		back.setMaximumSize(new Dimension(Integer.MAX_VALUE, 32));
		back.addActionListener(e -> onBack.run());

		// The artwork is the tile's identity — the site centres it and gives it room.
		imageLabel.setHorizontalAlignment(SwingConstants.CENTER);
		imageLabel.setAlignmentX(Component.CENTER_ALIGNMENT);
		imageLabel.setBorder(BorderFactory.createEmptyBorder(4, 0, 8, 0));

		title = centeredPane(Brand.bold(15f), Brand.TEXT_BRIGHT);

		status.setFont(FontManager.getRunescapeSmallFont());
		meta.setFont(FontManager.getRunescapeSmallFont());
		meta.setForeground(Brand.TEXT_DIM);

		tierLine.setFont(FontManager.getRunescapeSmallFont());
		tierLine.setForeground(Brand.TEXT_MAIN);
		tierLine.setBorder(BorderFactory.createEmptyBorder(4, 0, 0, 0));

		// The site gives the XP figure its own oversized readout, centred in a well;
		// it is the whole point of the tile, so it gets the same emphasis here.
		xpTotal.setFont(Brand.bold(22f));
		xpTotal.setForeground(Brand.TEXT_BRIGHT);
		xpTotal.setAlignmentX(Component.CENTER_ALIGNMENT);
		xpGoal.setFont(FontManager.getRunescapeSmallFont());
		xpGoal.setForeground(Brand.TEXT_DIM);
		xpGoal.setAlignmentX(Component.CENTER_ALIGNMENT);

		description = Brand.wrapping(FontManager.getRunescapeSmallFont(), Brand.TEXT_MAIN);

		for (Component c : new Component[]{back, title, status, meta,
			progress, tierLine, description, checklist})
		{
			((JComponent) c).setAlignmentX(Component.LEFT_ALIGNMENT);
		}

		descriptionWell.add(description);
		xpWell.add(Brand.centered(xpTotal));
		xpWell.add(Brand.centered(xpGoal));
		checklistWell.add(checklist);

		add(back);
		// The title sat directly against the button, which made the two read as one
		// block instead of a control and a heading.
		add(Box.createVerticalStrut(12));
		add(title);
		add(Brand.centered(imageLabel));
		add(Brand.centered(status));
		add(Brand.centered(meta));
		add(Box.createVerticalStrut(8));
		add(progress);
		add(tierLine);
		add(Box.createVerticalStrut(2));
		add(xpWell);
		add(descriptionHeading);
		add(descriptionWell);
		add(ratesHeading);
		add(rates);
		add(progressHeading);
		add(playerProgress);
		add(xpHeading);
		add(xpPlayers);
		submitAs.setFont(FontManager.getRunescapeSmallFont());
		submitAs.setForeground(Brand.TEXT_DIM);

		submitBox.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
		submitBox.setBackground(Brand.BG_WELL);
		submitBox.setForeground(Brand.TEXT_BRIGHT);
		submitBox.setFont(FontManager.getRunescapeSmallFont());

		submitButton.setFont(FontManager.getRunescapeSmallFont());
		submitButton.setMaximumSize(new Dimension(Integer.MAX_VALUE, 30));
		submitButton.addActionListener(e -> onSubmitClicked());

		for (Component c : new Component[]{submitAs, submitBox, submitGap, submitButton, submitStatus})
		{
			((JComponent) c).setAlignmentX(Component.LEFT_ALIGNMENT);
			submitWell.add(c);
		}

		add(checklistHeading);
		add(checklistWell);
		add(submitHeading);
		add(submitWell);
	}

	/** The tile currently shown, so the submit button knows what it is filing against. */
	private BoardModels.BoardTile showing;

	private void onSubmitClicked()
	{
		final BoardModels.SubmitOption option = (BoardModels.SubmitOption) submitBox.getSelectedItem();
		if (showing == null || option == null)
		{
			return;
		}

		submitButton.setEnabled(false);
		Brand.setWrapped(submitStatus, "Capturing…");
		submitter.submit(showing, option, message ->
		{
			Brand.setWrapped(submitStatus, message);
			submitButton.setEnabled(true);
		});
	}

	/**
	 * The submit controls, shown only when this character can actually use them:
	 * the tile has to take submissions, a codeword has to be configured, and the
	 * logged-in account has to be on the team being viewed. Anything else and the
	 * whole section stays hidden rather than offering a button that will fail.
	 */
	private void buildSubmit(BoardModels.BoardTile tile, BoardModels.Board board)
	{
		final String as = submitter.submittingAs();

		// No section at all when there is nothing to act on: not on this team, the
		// tile takes no submissions, or the tile is already finished. A tile can be
		// complete with items still unclaimed — "any 1 of 5" needs one — so the
		// remaining options are real but pointless, and offering them just invites
		// evidence a reviewer has to reject.
		final boolean eligible = as != null && !tile.done && !tile.submitItems.isEmpty();
		submitHeading.setVisible(eligible);
		submitWell.setVisible(eligible);
		if (!eligible)
		{
			return;
		}

		submitAs.setText("as " + as);
		submitButton.setEnabled(true);

		// Outside the event's window there is nothing to offer. The server rejects
		// these anyway; saying so here beats letting someone take a screenshot and
		// upload it only to be told no.
		final String closed = board.submissionsClosedReason();
		if (closed != null)
		{
			submitBox.setVisible(false);
			submitGap.setVisible(false);
			submitButton.setVisible(false);
			Brand.setWrapped(submitStatus, closed);
			return;
		}

		// Anything approved or already awaiting review is left out: offering it again
		// only produces a duplicate for a reviewer to reject.
		submitBox.removeAllItems();
		for (BoardModels.SubmitOption option : tile.submitItems)
		{
			if (!option.alreadySubmitted())
			{
				submitBox.addItem(option);
			}
		}

		final boolean anythingLeft = submitBox.getItemCount() > 0;
		submitBox.setVisible(anythingLeft);
		submitGap.setVisible(anythingLeft);
		submitButton.setVisible(anythingLeft);
		Brand.setWrapped(submitStatus, anythingLeft
			? ""
			: "Everything on this tile is already submitted or approved.");
	}

	void show(BoardModels.BoardTile tile, BoardModels.Board board)
	{
		final boolean showdown = board.isShowdown();

		// Header: the site writes "3 | Prison Break", dropping the position on
		// Showdown tiles where the tier matters more than the square.
		setCentered(title, showdown && tile.hasTierProgress()
			? tile.displayTitle()
			: tile.pos + " | " + tile.displayTitle());

		imageLabel.setIcon(null);
		final String url = config.showTileImages()
			? TileImageCache.resolve(siteUrl, tile.img)
			: null;
		if (url != null)
		{
			images.get(url, img -> imageLabel.setIcon(new ImageIcon(fit(img, 165, 110))));
		}

		if (showdown && tile.tier != null)
		{
			final int max = tile.maxTier == null ? 0 : tile.maxTier;
			status.setText("Tier " + tile.tier + " of " + max);
			status.setForeground(tile.tierMaxed() ? Brand.COMPLETED : Brand.TEXT_DIM);
		}
		else
		{
			status.setText(tile.done ? "Complete" : "Not complete");
			status.setForeground(tile.done ? Brand.COMPLETED : Brand.TEXT_DIM);
		}

		final StringBuilder m = new StringBuilder();
		m.append(tile.points).append(" PTS");
		if (tile.xp == null && (tile.hasCounts() || tile.neededCount() > 0))
		{
			m.append("  ·  ").append(tile.progressText()).append(" items");
		}
		meta.setText(m.toString());

		// Tags are deliberately not shown: they name the same bosses and skills that
		// Point Rates lists with their values attached, and on a 225px panel the
		// duplicate list cost several lines without adding anything.
		final boolean hasRates = !tile.rates.isEmpty();

		applyProgress(tile, showdown);

		final boolean hasDescription = tile.description != null && !tile.description.isEmpty();
		descriptionHeading.setVisible(hasDescription);
		descriptionWell.setVisible(hasDescription);
		if (hasDescription)
		{
			Brand.setWrapped(description, tile.description);
		}

		showing = tile;
		buildSubmit(tile, board);
		buildRates(tile);
		buildPlayerProgress(tile, hasRates);
		buildXp(tile);
		// A Showdown tile's items already appear in both sections above, priced and
		// attributed; the site drops the plain checklist there for the same reason.
		// An XP tile has no items at all — its breakdown replaces the checklist.
		buildChecklist(tile, board, !hasRates && tile.xp == null);

		revalidate();
		repaint();
	}

	private void applyProgress(BoardModels.BoardTile tile, boolean showdown)
	{
		if (showdown && tile.hasTierProgress())
		{
			progress.setVisible(true);
			tierLine.setVisible(true);

			if (tile.tierMaxed())
			{
				progress.setProgress(100, true);
				tierLine.setText("T" + tile.tier + " - " + Text.compact(tile.score) + " pts - MAX");
				return;
			}

			progress.setProgress(tile.pctToNextTier(), false);

			final String reached = (tile.tier == null || tile.tier == 0) ? "No tier" : ("T" + tile.tier);
			tierLine.setText(String.format("%s - %s / %s - %.1f%% to T%d",
				reached,
				Text.compact(tile.score),
				Text.compact(tile.nextTierAt()),
				tile.pctToNextTier(),
				(tile.tier == null ? 0 : tile.tier) + 1));
			return;
		}

		tierLine.setVisible(false);

		// An XP tile's bar tracks XP toward the goal; it has no items to count.
		if (tile.xp != null)
		{
			progress.setVisible(true);
			progress.setProgress(tile.xp.percent(), tile.done);
			return;
		}

		if (tile.done || tile.hasCounts() || tile.neededCount() > 0)
		{
			progress.setVisible(true);
			progress.setProgress(tile.itemsPercent(), tile.done);
		}
		else
		{
			progress.setVisible(false);
		}
	}

	/**
	 * An XP tile's readout: the team's total against the goal, then who earned it.
	 * These tiles carry no items, so this is all there is to show — previously the
	 * panel said "No item checklist on this tile" and left it at that.
	 */
	private void buildXp(BoardModels.BoardTile tile)
	{
		final BoardModels.XpProgress xp = tile.xp;
		final boolean present = xp != null;

		xpWell.setVisible(present);
		xpHeading.setVisible(present);
		xpPlayers.setVisible(present);
		xpPlayers.removeAll();

		if (!present)
		{
			return;
		}

		xpTotal.setText(THOUSANDS.format(Math.round(xp.collected)));
		xpTotal.setForeground(tile.done ? Brand.COMPLETED : Brand.TEXT_BRIGHT);
		xpGoal.setText("/ " + THOUSANDS.format(Math.round(xp.required)) + " XP");

		if (xp.players.isEmpty())
		{
			final JTextArea none = Brand.wrapping(FontManager.getRunescapeSmallFont(), Brand.TEXT_DIM);
			Brand.setWrapped(none, "No XP gained on this tile yet.");
			xpPlayers.add(none);
			return;
		}

		for (BoardModels.XpPlayer player : xp.players)
		{
			xpPlayers.add(Brand.valueRow(
				player.name == null ? "" : player.name,
				THOUSANDS.format(Math.round(player.xp)) + " XP",
				Brand.TEXT_BRIGHT,
				Brand.ACCENT,
				Brand.BG_WELL));
			xpPlayers.add(Box.createVerticalStrut(2));
		}
	}

	/** "Point Rates": what one kill / one XP / one drop is worth on this tile. */
	private void buildRates(BoardModels.BoardTile tile)
	{
		rates.removeAll();
		ratesHeading.setVisible(!tile.rates.isEmpty());
		rates.setVisible(!tile.rates.isEmpty());

		for (BoardModels.Rate rate : tile.rates)
		{
			rates.add(Brand.valueRow(
				rate.label == null ? "" : rate.label,
				rate.rate == null ? "" : rate.rate,
				Brand.TEXT_MAIN,
				Brand.TEXT_BRIGHT,
				Brand.BG_WELL));
			rates.add(Box.createVerticalStrut(2));
		}
	}

	/**
	 * "Player Progress": each teammate's total on this tile, then the kills, XP and
	 * drops that made it up.
	 *
	 * @param expected whether this tile should have a breakdown at all — the server
	 *                 only sends one for the tile that was asked for, so an empty
	 *                 list on a rates-bearing tile means "still loading", not "nobody
	 *                 has done anything".
	 */
	private void buildPlayerProgress(BoardModels.BoardTile tile, boolean expected)
	{
		playerProgress.removeAll();
		progressHeading.setVisible(expected);
		playerProgress.setVisible(expected);

		if (!expected)
		{
			return;
		}

		if (tile.players.isEmpty())
		{
			final JTextArea none = Brand.wrapping(FontManager.getRunescapeSmallFont(), Brand.TEXT_DIM);
			Brand.setWrapped(none, "No progress on this tile yet.");
			playerProgress.add(none);
			return;
		}

		for (BoardModels.PlayerProgress player : tile.players)
		{
			playerProgress.add(Brand.valueRow(
				player.name == null ? "" : player.name,
				Text.compact(player.points) + " pts",
				Brand.TEXT_BRIGHT,
				Brand.ACCENT,
				Brand.BG_WELL));

			for (BoardModels.ProgressLine line : player.lines)
			{
				playerProgress.add(Brand.valueRow(
					(line.label == null ? "" : line.label) + ": " + line.gainText(),
					Text.compact(line.points) + " pts",
					Brand.TEXT_DIM,
					Brand.TEXT_MAIN,
					Brand.BG_TILE));
			}

			playerProgress.add(Box.createVerticalStrut(6));
		}
	}

	private void buildChecklist(BoardModels.BoardTile tile, BoardModels.Board board, boolean show)
	{
		checklist.removeAll();
		checklistHeading.setVisible(show);
		checklistWell.setVisible(show);

		if (!show)
		{
			return;
		}

		for (BoardModels.TileItem item : tile.items)
		{
			final boolean done = item.approved >= item.need;
			checklist.add(row(
				item.label + (item.need > 1 ? (" (" + item.approved + "/" + item.need + ")") : ""),
				done,
				!done && item.pending > 0,
				item.player));
		}

		for (BoardModels.TileGroup group : tile.groups)
		{
			if (group.name != null && !group.name.isEmpty())
			{
				final JTextArea header = Brand.wrapping(FontManager.getRunescapeSmallFont(), Brand.ACCENT);
				Brand.setWrapped(header, group.name + logicSuffix(group.logic));
				header.setBorder(BorderFactory.createEmptyBorder(8, 0, 2, 0));
				checklist.add(header);
			}
			for (BoardModels.TileGroupItem gi : group.items)
			{
				checklist.add(row(gi.label, gi.approved, gi.pending, gi.player));
			}
		}

		if (tile.items.isEmpty() && tile.groups.isEmpty())
		{
			final JTextArea none = Brand.wrapping(FontManager.getRunescapeSmallFont(), Brand.TEXT_DIM);
			Brand.setWrapped(none, board.hiddenTiles
				? "Tiles are hidden on this event."
				: "No item checklist on this tile.");
			checklist.add(none);
		}
	}

	private static String logicSuffix(String logic)
	{
		if (logic == null)
		{
			return "";
		}
		switch (logic)
		{
			case "any1":
				return " (any 1)";
			case "any2":
				return " (any 2)";
			case "any3":
				return " (any 3)";
			case "any4":
				return " (any 4)";
			default:
				return "";
		}
	}

	/**
	 * A checklist line in one of three states, as the site draws them: approved,
	 * awaiting review, or untouched. Without the middle one an item someone has
	 * already submitted proof for looks identical to one nobody has attempted.
	 */
	/** A fixed-height transparent strut that BoxLayout will not stretch. */
	private static JPanel spacer(int height)
	{
		final JPanel p = new JPanel();
		p.setOpaque(false);
		p.setPreferredSize(new Dimension(1, height));
		p.setMinimumSize(new Dimension(1, height));
		p.setMaximumSize(new Dimension(Integer.MAX_VALUE, height));
		return p;
	}

	private static JTextArea row(String label, boolean approved, boolean pending, String player)
	{
		final Color colour;
		final String mark;
		if (approved)
		{
			colour = Brand.COMPLETED;
			mark = "✓  ";
		}
		else if (pending)
		{
			colour = Brand.ACCENT;
			mark = "?  ";
		}
		else
		{
			colour = Brand.TEXT_DIM;
			mark = "○  ";
		}

		// The site names the submitter next to the item, which is how a team sees at a
		// glance who already covered something.
		final String who = (player == null || player.trim().isEmpty()) ? "" : (" (" + player.trim() + ")");

		final JTextArea ta = Brand.wrapping(FontManager.getRunescapeSmallFont(), colour);
		Brand.setWrapped(ta, mark + label + who);
		ta.setBorder(BorderFactory.createEmptyBorder(2, 0, 2, 0));
		return ta;
	}

	/**
	 * Centre-aligned wrapping text. A JTextArea can't centre its lines, and an HTML
	 * JLabel brings back the width-hint clipping, so the tile title uses a text pane
	 * with a centred paragraph style.
	 */
	private static javax.swing.JTextPane centeredPane(Font font, Color foreground)
	{
		final javax.swing.JTextPane pane = new javax.swing.JTextPane();
		pane.setEditable(false);
		pane.setFocusable(false);
		pane.setOpaque(false);
		pane.setBorder(BorderFactory.createEmptyBorder(2, 0, 2, 0));
		pane.setFont(font);
		pane.setForeground(foreground);
		pane.setAlignmentX(Component.LEFT_ALIGNMENT);

		if (pane.getCaret() instanceof DefaultCaret)
		{
			((DefaultCaret) pane.getCaret()).setUpdatePolicy(DefaultCaret.NEVER_UPDATE);
		}
		return pane;
	}

	/** Sets a centred pane's text; alignment has to be re-applied after each change. */
	private static void setCentered(javax.swing.JTextPane pane, String text)
	{
		pane.setText(text);

		final javax.swing.text.SimpleAttributeSet centre = new javax.swing.text.SimpleAttributeSet();
		javax.swing.text.StyleConstants.setAlignment(centre, javax.swing.text.StyleConstants.ALIGN_CENTER);
		pane.getStyledDocument().setParagraphAttributes(0, pane.getDocument().getLength(), centre, false);

		pane.setSize(Brand.CONTENT_WIDTH, Short.MAX_VALUE);
	}

	private static BufferedImage fit(BufferedImage src, int maxW, int maxH)
	{
		final double scale = Math.min(maxW / (double) src.getWidth(), maxH / (double) src.getHeight());
		if (scale >= 1)
		{
			return src;
		}
		final int w = Math.max(1, (int) Math.round(src.getWidth() * scale));
		final int h = Math.max(1, (int) Math.round(src.getHeight() * scale));
		final BufferedImage out = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = out.createGraphics();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
			g.drawImage(src, 0, 0, w, h, null);
		}
		finally
		{
			g.dispose();
		}
		return out;
	}
}

package com.rsbingo;

import com.google.inject.Provides;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import java.awt.image.BufferedImage;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;
import javax.swing.SwingUtilities;

@Slf4j
@PluginDescriptor(
	name = "RS-Bingo",
	description = "Follow an rs-bingo.com bingo event: your team's board, tile progress and standings, with optional in-client submissions",
	tags = {"bingo", "clan", "event", "board"}
)
public class RsBingoPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private RsBingoConfig config;

	@Inject
	private RsBingoApi api;

	@Inject
	private TileImageCache images;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ScheduledExecutorService executor;

	@Inject
	private net.runelite.client.ui.DrawManager drawManager;

	private RsBingoPanel panel;
	private NavigationButton navButton;
	/** Kept so a rebuilt panel can be handed these again without re-fetching. */
	private BoardModels.ThemeList themes;
	private BoardModels.EventList myEvents;
	/** The character already reported to the panel, so ticks don't re-report it. */
	private String knownPlayer;
	private ScheduledFuture<?> refreshTask;

	@Provides
	RsBingoConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(RsBingoConfig.class);
	}

	@Override
	protected void startUp()
	{
		buildPanel();

		final BufferedImage icon = ImageUtil.loadImageResource(getClass(), "/panel_icon.png");
		navButton = NavigationButton.builder()
			.tooltip("RS-Bingo")
			.icon(icon)
			// Sidebar order: NavigationButton.COMPARATOR sorts on priority ascending
			// (then tooltip), so a lower number sits higher up.
			.priority(1)
			.panel(panel)
			.build();

		clientToolbar.addNavigation(navButton);

		loadThemes();
		loadMyEvents();

		if (!config.eventCode().trim().isEmpty())
		{
			loadEvent();
		}

		scheduleRefresh();
	}

	private void buildPanel()
	{
		panel = new RsBingoPanel(api, images, config, RsBingoConfig.SITE_URL,
			this::loadEvent, this::rememberTeam,
			this::applyTheme, this::switchEvent, drawManager::requestNextFrameListener);
	}

	/**
	 * List the linked account's events in the panel. Silent when no token is set:
	 * linking is optional, and an event code alone still works.
	 */
	private void loadMyEvents()
	{
		final String token = config.accountToken();
		if (token == null || token.trim().isEmpty())
		{
			return;
		}

		api.fetchMyEvents(RsBingoConfig.SITE_URL, token,
			list ->
			{
				myEvents = list;
				if (panel != null)
				{
					panel.setMyEvents(list);
				}
			},
			error -> log.debug("rs-bingo event list: {}", error));
	}

	/** Load an event picked from the panel's dropdown, remembering it as the current one. */
	private void switchEvent(String eventId)
	{
		if (eventId == null || eventId.trim().isEmpty())
		{
			return;
		}
		// Writing the config is what makes the choice stick; the change handler then
		// loads it, so there is one path into "show me this event".
		configManager.setConfiguration(RsBingoConfig.GROUP, "eventCode", eventId.trim().toUpperCase());
	}

	/** Offer the site's themes in the panel, and re-apply the one already chosen. */
	private void loadThemes()
	{
		api.fetchThemes(RsBingoConfig.SITE_URL, list ->
		{
			themes = list;

			final String saved = config.theme();
			if (saved != null && !saved.isEmpty())
			{
				for (BoardModels.Theme theme : list.themes)
				{
					if (saved.equals(theme.key))
					{
						SwingUtilities.invokeLater(() -> repaintWithTheme(theme));
						break;
					}
				}
			}

			if (panel != null)
			{
				panel.setThemes(list);
			}
		});
	}

	/**
	 * Switch the panel to a theme and remember it.
	 *
	 * Components read the palette when they are created, so the panel rebuilds its
	 * contents rather than trying to recolour them in place: miss one and it keeps
	 * the old theme's colours, which looks like a bug rather than a stale pixel.
	 */
	private void applyTheme(BoardModels.Theme theme)
	{
		if (theme == null || theme.key == null)
		{
			return;
		}
		configManager.setConfiguration(RsBingoConfig.GROUP, "theme", theme.key);
		repaintWithTheme(theme);
	}

	private void repaintWithTheme(BoardModels.Theme theme)
	{
		Brand.applyPalette(theme.vars);

		// Rebuild the panel's contents, not the panel. Replacing it meant removing and
		// re-adding the navigation button, which collapsed the sidebar every time —
		// and re-opening it programmatically did not reliably put it back.
		if (panel != null)
		{
			panel.reskin();
		}
	}

	@Override
	protected void shutDown()
	{
		cancelRefresh();
		clientToolbar.removeNavigation(navButton);
		panel = null;
		navButton = null;
	}

	/**
	 * Forget the character on the way out, so switching accounts is picked up rather
	 * than leaving the previous one's name in place.
	 */
	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() != GameState.LOGGED_IN)
		{
			knownPlayer = null;
		}
	}

	/**
	 * Pick up the logged-in character, which decides whether the submit controls
	 * appear at all.
	 *
	 * Read on a tick rather than on GameState.LOGGED_IN: at the moment that event
	 * fires getLocalPlayer() is usually still null, so reading it there silently
	 * missed the name and left the panel thinking nobody was logged in. Guarded on
	 * knownPlayer so this costs one reference comparison per tick once settled.
	 */
	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (panel == null)
		{
			return;
		}

		final Player local = client.getLocalPlayer();
		if (local == null)
		{
			return;
		}

		final String name = local.getName();
		if (name == null || name.equals(knownPlayer))
		{
			return;
		}

		knownPlayer = name;
		panel.setLocalPlayer(name);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!RsBingoConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}

		if ("refreshSeconds".equals(event.getKey()))
		{
			scheduleRefresh();
			return;
		}

		if ("eventCode".equals(event.getKey()))
		{
			loadEvent();
			return;
		}

		// Pasting a token has to take effect immediately: the event list is the whole
		// point of linking, and making someone restart the client to see it reads as
		// the link having silently failed.
		if ("accountToken".equals(event.getKey()))
		{
			loadMyEvents();
			return;
		}

		// Toggling artwork only changes how the board draws, so redraw it rather than
		// starting the whole event over.
		if ("showTileImages".equals(event.getKey()) && panel != null)
		{
			panel.refreshCurrentTeam();
		}
	}

	/**
	 * Fetch the event summary and team list. The panel picks a team and asks for its
	 * board, so this is the single entry point for "start over".
	 *
	 * The code comes from the config, which is now the only place it lives — the
	 * panel used to carry its own copy and write it back, which fought with edits
	 * made in the settings pane.
	 */
	private void loadEvent()
	{
		if (panel == null)
		{
			return;
		}

		final String code = config.eventCode() == null ? "" : config.eventCode().trim();
		if (code.isEmpty())
		{
			panel.clearBoard();
			panel.setStatus("Set an event code in the plugin settings.");
			return;
		}

		panel.setStatus("Loading…");
		api.fetchBoard(RsBingoConfig.SITE_URL, code.toUpperCase(), null, panel::showEvent, panel::setStatus);
	}

	/**
	 * Persist the panel's team choice. A code pointing at a different event simply
	 * won't match this name, and the panel falls back to the leading team.
	 */
	private void rememberTeam(String team)
	{
		if (team != null && !team.equals(config.selectedTeam()))
		{
			configManager.setConfiguration(RsBingoConfig.GROUP, "selectedTeam", team);
		}
	}

	private void scheduleRefresh()
	{
		cancelRefresh();

		final int seconds = config.refreshSeconds();
		if (seconds <= 0)
		{
			return;
		}

		// Floor at 15s so a mistyped config can't hammer the site.
		final long period = Math.max(15, seconds);
		refreshTask = executor.scheduleWithFixedDelay(
			() ->
			{
				if (panel != null)
				{
					panel.refreshCurrentTeam();
				}
			},
			period, period, TimeUnit.SECONDS);
	}

	private void cancelRefresh()
	{
		if (refreshTask != null)
		{
			refreshTask.cancel(false);
			refreshTask = null;
		}
	}
}

package com.rsbingo;

import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JTextArea;
import javax.swing.text.DefaultCaret;
import javax.swing.JPanel;
import net.runelite.client.ui.FontManager;

/**
 * The site's look, in Swing.
 *
 * Colours are the "Obsidian Gold" theme from js/themes.js — the project's default
 * and the one every screenshot is taken in — rather than anything invented here.
 * The names map one-to-one onto the CSS custom properties so the two can be
 * compared: {@code --bg-well} is {@link #BG_WELL}, {@code --accent} is
 * {@link #ACCENT}, and so on.
 *
 * The visual grammar is the same as the modal's: gold uppercase section labels
 * above near-black rounded "wells" that hold the content.
 */
final class Brand
{
	// The live palette. Not final: the panel can be switched to any of the site's
	// themes at runtime. These starting values are Obsidian Gold, the site's default,
	// and are what the panel falls back to if the theme endpoint can't be reached —
	// so a missing server means "looks as shipped", never "loses its styling".
	/** --bg-tile: the panel itself. */
	static Color BG_TILE = new Color(0x141410);
	/** --bg-well: recessed boxes inside it. */
	static Color BG_WELL = new Color(0x040404);
	/** --bg-completed-well: the same box on a finished tile. */
	static Color BG_COMPLETED_WELL = new Color(0x1A1408);
	/** --border-main */
	static Color BORDER = new Color(0x2A2820);
	/** --accent */
	static Color ACCENT = new Color(0xD8A830);
	/** --text-main */
	static Color TEXT_MAIN = new Color(0xC09828);
	/** --text-bright */
	static Color TEXT_BRIGHT = new Color(0xF0D888);
	/** --text-dim */
	static Color TEXT_DIM = new Color(0x706858);
	/** --text-completed */
	static Color COMPLETED = new Color(0xD8A830);

	/**
	 * Repaints the palette from one of the site's themes.
	 *
	 * Keys are the CSS custom properties as js/themes.js writes them, so the mapping
	 * below is the whole translation layer between the website's styling and this
	 * panel's. Anything absent keeps its current value rather than defaulting to
	 * black, which is what a partial theme would otherwise produce.
	 */
	static void applyPalette(java.util.Map<String, String> vars)
	{
		if (vars == null || vars.isEmpty())
		{
			return;
		}

		BG_TILE = parse(vars.get("--bg-tile"), BG_TILE);
		BG_WELL = parse(vars.get("--bg-well"), BG_WELL);
		BG_COMPLETED_WELL = parse(vars.get("--bg-completed-well"), BG_COMPLETED_WELL);
		BORDER = parse(vars.get("--border-main"), BORDER);
		ACCENT = parse(vars.get("--accent"), ACCENT);
		TEXT_MAIN = parse(vars.get("--text-main"), TEXT_MAIN);
		TEXT_BRIGHT = parse(vars.get("--text-bright"), TEXT_BRIGHT);
		TEXT_DIM = parse(vars.get("--text-dim"), TEXT_DIM);
		COMPLETED = parse(vars.get("--text-completed"), COMPLETED);
	}

	/** "#d8a830" -> Color, keeping the old value on anything unparseable. */
	private static Color parse(String hex, Color fallback)
	{
		if (hex == null)
		{
			return fallback;
		}
		final String v = hex.trim().replace("#", "");
		if (v.length() != 6)
		{
			return fallback;
		}
		try
		{
			return new Color(Integer.parseInt(v, 16));
		}
		catch (NumberFormatException e)
		{
			return fallback;
		}
	}

	private static final int RADIUS = 6;

	/** RuneLite's fixed side-panel width. */
	static final int PANEL_WIDTH = 225;
	/** Outer insets used by both cards, per side. */
	static final int PAD = 4;
	/** The vertical scrollbar, which is always allowed for so text never reflows. */
	static final int SCROLLBAR = 8;

	/** Full width for a standalone block: the panel less padding and the scrollbar. */
	static final int CONTENT_WIDTH = PANEL_WIDTH - (PAD * 4) - SCROLLBAR;

	/** The same less a row's own padding. */
	static final int ROW_WIDTH = CONTENT_WIDTH - (PAD * 2);
	static final int ROW_GAP = 4;

	private Brand()
	{
	}

	/**
	 * A label that wraps: read-only, transparent, no border — styled to look like a
	 * JLabel but able to break across lines.
	 *
	 * A JTextArea rather than an HTML JLabel because Swing treats {@code width:Npx}
	 * as a hint, not a constraint, and long text rendered past the panel and lost its
	 * right edge mid-word. Plain text also can't be tripped up by markup in an
	 * organiser's tile description.
	 */
	static JTextArea wrapping(Font font, Color foreground)
	{
		final JTextArea ta = new JTextArea();
		ta.setLineWrap(true);
		ta.setWrapStyleWord(true);
		ta.setEditable(false);
		ta.setFocusable(false);
		ta.setOpaque(false);
		ta.setBorder(null);
		ta.setFont(font);
		ta.setForeground(foreground);
		ta.setAlignmentX(Component.LEFT_ALIGNMENT);

		// Without this, setText() moves the caret and the text area drags the
		// enclosing scroll pane down to follow it.
		if (ta.getCaret() instanceof DefaultCaret)
		{
			((DefaultCaret) ta.getCaret()).setUpdatePolicy(DefaultCaret.NEVER_UPDATE);
		}
		return ta;
	}

	/**
	 * Sets a wrapping block's text and tells it the width it will be laid out at.
	 * Without the width it reports the height of a single line and everything past
	 * the first wrap is clipped — the more so once a scrollbar takes another 8px.
	 */
	static void setWrapped(JTextArea area, String text)
	{
		area.setText(text);
		area.setSize(CONTENT_WIDTH, Short.MAX_VALUE);
	}

	/**
	 * A label/value row. The value keeps its natural width on the right and the label
	 * takes what's left and wraps into it — at this width "Boss: Corrupted Gauntlet"
	 * and "12000 pts/KC" do not fit on one line, and the alternative is one of them
	 * being clipped.
	 */
	static JPanel valueRow(String left, String right, Color leftColor, Color rightColor, Color background)
	{
		final JPanel row = new JPanel(new java.awt.BorderLayout(ROW_GAP, 0))
		{
			@Override
			public Dimension getMaximumSize()
			{
				// Height follows the wrapped label; without this BoxLayout stretches
				// the row to soak up leftover vertical space.
				return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
			}
		};
		row.setBackground(background);
		row.setOpaque(background != null);
		row.setBorder(BorderFactory.createEmptyBorder(2, PAD, 2, PAD));
		row.setAlignmentX(Component.LEFT_ALIGNMENT);

		final JTextArea label = wrapping(FontManager.getRunescapeSmallFont(), leftColor);
		label.setText(left);

		final JLabel value = new JLabel(right);
		value.setFont(FontManager.getRunescapeSmallFont());
		value.setForeground(rightColor);
		value.setVerticalAlignment(javax.swing.SwingConstants.TOP);

		// A JTextArea works out its wrapped height from its current width, and inside
		// a BorderLayout it is asked for that height before it has been given one — so
		// it answers "one line" and the rest of the label is cut off. Tell it the
		// width it is going to get.
		final int labelWidth = Math.max(40, ROW_WIDTH - value.getPreferredSize().width - ROW_GAP);
		label.setSize(labelWidth, Short.MAX_VALUE);

		row.add(label, java.awt.BorderLayout.CENTER);
		row.add(value, java.awt.BorderLayout.EAST);
		return row;
	}

	/** A vertical stack of rows. Transparent, so a well behind it shows through. */
	static JPanel section()
	{
		final JPanel p = new JPanel();
		p.setLayout(new BoxLayout(p, BoxLayout.Y_AXIS));
		p.setOpaque(false);
		p.setAlignmentX(Component.LEFT_ALIGNMENT);
		return p;
	}

	/** A gold uppercase section label, as the modal sets them. */
	static JLabel sectionLabel(String text)
	{
		final JLabel l = new JLabel(text.toUpperCase());
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(ACCENT);
		l.setBorder(BorderFactory.createEmptyBorder(10, PAD - 2, 4, PAD - 2));
		l.setAlignmentX(Component.LEFT_ALIGNMENT);
		return l;
	}

	/** A recessed rounded box. Stacks its children vertically. */
	static JPanel well()
	{
		final RoundedPanel p = new RoundedPanel(BG_WELL, BORDER);
		p.setLayout(new BoxLayout(p, BoxLayout.Y_AXIS));
		p.setBorder(BorderFactory.createEmptyBorder(6, PAD + 2, 6, PAD + 2));
		p.setAlignmentX(Component.LEFT_ALIGNMENT);
		return p;
	}

	/**
	 * A button drawn the way {@link #well()} draws a panel: same corner radius, same
	 * fill, so a control and a section read as parts of one surface rather than a
	 * rounded box with a square button sitting on it.
	 *
	 * Swing will not round a JButton for us. The look-and-feel is told to fill
	 * nothing ({@code setContentAreaFilled(false)}) and the component is not opaque,
	 * so the only thing painting a background is the rounded rectangle below;
	 * {@code super.paintComponent} then draws the label over it.
	 *
	 * Colours are read at paint time, not captured here, so a theme change applies
	 * without rebuilding the button.
	 */
	static JButton button(String text, Color foreground)
	{
		final JButton b = new JButton(text)
		{
			@Override
			protected void paintComponent(Graphics graphics)
			{
				final Graphics2D g = (Graphics2D) graphics.create();
				try
				{
					g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

					// Pressed lifts to the tile colour: without it nothing on screen
					// acknowledges the click until the panel has already changed.
					g.setColor(getModel().isPressed() ? BG_TILE : BG_WELL);
					g.fillRoundRect(0, 0, getWidth() - 1, getHeight() - 1, RADIUS, RADIUS);

					// A disabled button keeps the shape but drops out of the accent,
					// so "nothing left to submit" doesn't look like something to press.
					g.setColor(isEnabled() ? ACCENT : BORDER);
					g.drawRoundRect(0, 0, getWidth() - 1, getHeight() - 1, RADIUS, RADIUS);
				}
				finally
				{
					g.dispose();
				}
				super.paintComponent(graphics);
			}
		};

		b.setFocusPainted(false);
		b.setContentAreaFilled(false);
		b.setOpaque(false);
		b.setForeground(foreground);
		b.setBorder(BorderFactory.createEmptyBorder(7, 8, 7, 8));
		return b;
	}

	/** A small gold-outlined pill, for the points count and tag chips. */
	static JPanel badge(String text, Color foreground)
	{
		final RoundedPanel p = new RoundedPanel(null, foreground.darker());
		p.setLayout(new BoxLayout(p, BoxLayout.X_AXIS));
		p.setBorder(BorderFactory.createEmptyBorder(1, 5, 1, 5));

		final JLabel l = new JLabel(text);
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(foreground);
		p.add(l);

		// Pills must not stretch to the panel width when stacked vertically.
		p.setMaximumSize(new Dimension(Integer.MAX_VALUE, 18));
		p.setAlignmentX(Component.LEFT_ALIGNMENT);
		return p;
	}

	static Font bold(float size)
	{
		return FontManager.getRunescapeBoldFont().deriveFont(size);
	}

	/**
	 * Centres a component across the full panel width.
	 *
	 * Setting {@code CENTER_ALIGNMENT} on one child of a BoxLayout whose siblings are
	 * left-aligned does not do this — the layout reconciles the mixed alignments and
	 * the component ends up somewhere arbitrary. A full-width wrapper that centres
	 * its own child is unambiguous.
	 */
	static JPanel centered(Component inner)
	{
		final JPanel p = new JPanel(new java.awt.GridBagLayout())
		{
			@Override
			public Dimension getMaximumSize()
			{
				return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
			}
		};
		p.setOpaque(false);
		p.setAlignmentX(Component.LEFT_ALIGNMENT);
		p.add(inner);
		return p;
	}

	/**
	 * A panel with rounded corners.
	 *
	 * Swing has no rounded background, so the fill and border are painted here and
	 * the component is left non-opaque — otherwise the square default background
	 * paints over the corners.
	 */
	static class RoundedPanel extends JPanel
	{
		private final Color fill;
		private final Color line;

		RoundedPanel(Color fill, Color line)
		{
			this.fill = fill;
			this.line = line;
			setOpaque(false);
		}

		@Override
		protected void paintComponent(Graphics graphics)
		{
			final Graphics2D g = (Graphics2D) graphics.create();
			try
			{
				g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
				if (fill != null)
				{
					g.setColor(fill);
					g.fillRoundRect(0, 0, getWidth() - 1, getHeight() - 1, RADIUS, RADIUS);
				}
				if (line != null)
				{
					g.setColor(line);
					g.drawRoundRect(0, 0, getWidth() - 1, getHeight() - 1, RADIUS, RADIUS);
				}
			}
			finally
			{
				g.dispose();
			}
			super.paintComponent(graphics);
		}
	}

	/**
	 * The modal's progress bar: a dark rounded track with a gold gradient fill.
	 * Swing's JProgressBar can't be talked into rounded ends or a gradient without
	 * a custom UI delegate, which is more code than simply drawing it.
	 */
	static class ProgressBar extends JPanel
	{
		private double percent;
		private boolean complete;

		ProgressBar()
		{
			setOpaque(false);
			setPreferredSize(new Dimension(10, 8));
			setMaximumSize(new Dimension(Integer.MAX_VALUE, 8));
			setAlignmentX(Component.LEFT_ALIGNMENT);
		}

		void setProgress(double pct, boolean isComplete)
		{
			this.percent = Math.max(0, Math.min(100, pct));
			this.complete = isComplete;
			repaint();
		}

		@Override
		protected void paintComponent(Graphics graphics)
		{
			final Graphics2D g = (Graphics2D) graphics.create();
			try
			{
				g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
				final int w = getWidth();
				final int h = getHeight();

				g.setColor(BG_WELL);
				g.fillRect(0, 0, w - 1, h - 1);
				g.setColor(BORDER);
				g.drawRect(0, 0, w - 1, h - 1);

				final int fillWidth = (int) Math.round((w - 2) * (percent / 100.0));
				if (fillWidth <= 0)
				{
					return;
				}

				// Darker gold to bright gold, left to right — the same sweep the site
				// uses, which reads as progress even at eight pixels tall.
				//
				// Square ends, so the fill's width is exactly the percentage. Rounded
				// caps had to be padded to at least the bar's height or they collapsed
				// into a lens shape, which overstated small values.
				g.setPaint(new GradientPaint(
					0, 0, complete ? COMPLETED.darker() : TEXT_MAIN.darker(),
					fillWidth, 0, complete ? TEXT_BRIGHT : ACCENT));
				g.fillRect(1, 1, fillWidth, h - 3);
			}
			finally
			{
				g.dispose();
			}
		}
	}
}

package com.rsbingo;

import java.util.ArrayList;
import java.util.List;

/**
 * The shape of plugin_board.php's response. Field names match the JSON exactly so
 * Gson can map it with no annotations.
 *
 * Note what is NOT here: no scoring inputs, no snapshots, no submissions. The
 * server decides what is complete and how many points a team has; this plugin only
 * draws the answer. That keeps one scoring implementation instead of adding a
 * sixth in a language the rest of the project doesn't use.
 */
public class BoardModels
{
	public static class Board
	{
		public String eventId;
		public String name;
		public String format;
		public int cols;
		public int rows;
		public int numTiers;
		public String startDate;
		public String endDate;
		public List<TeamSummary> teams = new ArrayList<>();

		/**
		 * The event's codeword, sent only once the site itself would show it. Stamped
		 * onto submission screenshots and used to authorise the submission, so the
		 * player never has to type it anywhere. Null while still withheld.
		 */
		public String codeword;

		/** Only present when a team was requested. */
		public String team;
		public List<BoardTile> board = new ArrayList<>();
		public boolean hiddenTiles;

		public boolean isShowdown()
		{
			return "Showdown".equals(format);
		}

		/** Submissions are only open between the start and end dates. */
		public boolean submissionsOpen()
		{
			return Text.withinEventWindow(startDate, endDate, java.time.Instant.now());
		}

		/** Why submissions are shut, or null when they are open. */
		public String submissionsClosedReason()
		{
			final java.time.Instant now = java.time.Instant.now();
			if (Text.withinEventWindow(startDate, endDate, now))
			{
				return null;
			}
			// Outside the window is one of exactly two things, and the countdown line
			// above already tells them which; this names it in the submit box too.
			return Text.startsAfter(startDate, now)
				? "This event has not started yet."
				: "This event has ended.";
		}
	}

	/** plugin_events.php: the events a linked account belongs to. */
	public static class EventList
	{
		public String username;
		public List<EventSummary> events = new ArrayList<>();
	}

	public static class EventSummary
	{
		public String eventId;
		public String name;
		public String role;
		public String format;
		public String startDate;
		public String endDate;

		@Override
		public String toString()
		{
			// The event dropdown renders this directly. The code is worth showing:
			// it is what someone reads out to a teammate who has not linked an account.
			return (name == null || name.isEmpty() ? eventId : name) + "  (" + eventId + ")";
		}
	}

	/** plugin_themes.php: the site's colour themes. */
	public static class ThemeList
	{
		public String defaultKey;
		public List<Theme> themes = new ArrayList<>();
	}

	public static class Theme
	{
		public String key;
		public String label;
		/** CSS custom properties, e.g. "--accent" -> "#d8a830". */
		public java.util.Map<String, String> vars = new java.util.HashMap<>();

		@Override
		public String toString()
		{
			// The theme dropdown renders this directly.
			return label == null ? (key == null ? "" : key) : label;
		}
	}

	public static class TeamSummary
	{
		public String name;
		public int points;
		public List<String> players = new ArrayList<>();

		@Override
		public String toString()
		{
			// The team dropdown renders this directly.
			return name == null ? "" : name;
		}
	}

	public static class BoardTile
	{
		public int pos;
		public int id;
		public String title;
		public String description;
		public String img;
		public int points;
		public int goal;
		public boolean done;
		public boolean empty;
		public List<String> tags = new ArrayList<>();
		public List<TileItem> items = new ArrayList<>();
		public List<TileGroup> groups = new ArrayList<>();

		/** Showdown only; 0 on other formats. */
		public Integer tier;
		public Integer maxTier;

		/**
		 * Showdown only, and only on tiles that actually have uimTags: the raw tile
		 * score and the points one tier costs. The server derives {@link #tier} from
		 * exactly these two, so the "x% to T3" line below cannot disagree with it.
		 */
		public Double score;
		public Integer tierThreshold;

		/**
		 * What each boss/skill/activity/item on this tile is worth — the site's
		 * "Point Rates" card. Present on every Showdown tile; it is small and static.
		 */
		public List<Rate> rates = new ArrayList<>();

		/**
		 * Who earned what, the site's "Player Progress" card. Only sent for the tile
		 * the panel asked about (`&tile=N`), because it is the bulk of the response —
		 * so this is empty on every other tile and null-safe to iterate.
		 */
		public List<PlayerProgress> players = new ArrayList<>();

		/**
		 * Set only on XP tiles, which are judged on snapshot XP rather than items —
		 * their checklist is always empty, so without this the panel had nothing to
		 * show for them.
		 */
		public XpProgress xp;

		/**
		 * Everything on this tile a player could submit, with the array indices
		 * submit_item.php expects. Empty when the tile takes no submissions, which is
		 * what hides the submit controls.
		 */
		public List<SubmitOption> submitItems = new ArrayList<>();

		public boolean hasTierProgress()
		{
			return score != null && tierThreshold != null && tierThreshold > 0;
		}

		/** True once every tier is banked — the site labels this "MAX". */
		public boolean tierMaxed()
		{
			return tier != null && maxTier != null && maxTier > 0 && tier >= maxTier;
		}

		/** Score at which the next tier lands. Meaningless once maxed. */
		public double nextTierAt()
		{
			if (!hasTierProgress())
			{
				return 0;
			}
			return ((tier == null ? 0 : tier) + 1) * (double) tierThreshold;
		}

		/** 0..100 toward the next tier. */
		public double pctToNextTier()
		{
			final double target = nextTierAt();
			if (target <= 0)
			{
				return 0;
			}
			return Math.max(0, Math.min(100, (score / target) * 100.0));
		}

		public String displayTitle()
		{
			if (empty)
			{
				return "";
			}
			return (title == null || title.isEmpty()) ? ("Tile " + pos) : title;
		}

		/**
		 * The counts the server judged completion on. Not derivable here: a group
		 * capped by "any 1" contributes once no matter how many options it lists, so
		 * summing the checklist gives a different — and wrong — answer. A Godsword
		 * tile needing 3 shards plus any 1 of 5 hilts is 1/4 done, not 1/8.
		 *
		 * Null when talking to a server that predates these fields; callers fall back
		 * to the checklist sums below.
		 */
		public Integer collected;
		public Integer required;

		public boolean hasCounts()
		{
			return collected != null && required != null && required > 0;
		}

		/** 0..100 for a non-Showdown tile, from the server's counts where available. */
		public double itemsPercent()
		{
			if (done)
			{
				return 100;
			}
			if (hasCounts())
			{
				return Math.max(0, Math.min(100, (collected * 100.0) / required));
			}
			final int needed = neededCount();
			return needed <= 0 ? 0 : Math.max(0, Math.min(100, (approvedCount() * 100.0) / needed));
		}

		/** "1/4" as the server counts it, else the checklist's own tally. */
		public String progressText()
		{
			return hasCounts()
				? (collected + "/" + required)
				: (approvedCount() + "/" + neededCount());
		}

		/** Approved / needed across the flat item list, for the grid's progress line. */
		public int approvedCount()
		{
			int n = 0;
			for (TileItem i : items)
			{
				n += i.approved;
			}
			for (TileGroup g : groups)
			{
				for (TileGroupItem gi : g.items)
				{
					if (gi.approved)
					{
						n++;
					}
				}
			}
			return n;
		}

		public int neededCount()
		{
			int n = 0;
			for (TileItem i : items)
			{
				n += i.need;
			}
			for (TileGroup g : groups)
			{
				n += g.items.size();
			}
			return n;
		}
	}

	/** An XP tile's team total against its goal, and who contributed. */
	public static class XpProgress
	{
		public String skill;
		public double collected;
		public double required;
		public List<XpPlayer> players = new ArrayList<>();

		/** 0..100 toward the goal. */
		public double percent()
		{
			if (required <= 0)
			{
				return 0;
			}
			return Math.max(0, Math.min(100, (collected / required) * 100.0));
		}
	}

	public static class XpPlayer
	{
		public String name;
		public double xp;
	}

	/** One submittable item, carrying the indices the submission endpoint wants. */
	public static class SubmitOption
	{
		public String label;
		public String type;
		public int index;
		public int groupIndex;
		public int itemIndex;
		public boolean approved;
		public boolean pending;

		/** Already approved or awaiting review, so there is nothing to file again. */
		public boolean alreadySubmitted()
		{
			return approved || pending;
		}

		@Override
		public String toString()
		{
			// The submit dropdown renders this directly.
			return label == null ? "" : label;
		}
	}

	/** One row of the point-rates table: "Boss: Nex" / "6000 pts/KC". */
	public static class Rate
	{
		public String label;
		public String rate;
	}

	public static class PlayerProgress
	{
		public String name;
		public double points;
		public List<ProgressLine> lines = new ArrayList<>();
	}

	/** One earning: "Nex", +163, "KC", 978000 points. */
	public static class ProgressLine
	{
		public String label;
		public double gain;
		public String unit;
		public double points;

		/** Items are counted ("x3"); everything else is a gain ("+163 KC"). */
		public String gainText()
		{
			if ("item".equals(unit))
			{
				return "x" + Text.compact(gain);
			}
			return "+" + Text.compact(gain) + (unit == null || unit.isEmpty() ? "" : " " + unit);
		}
	}

	public static class TileItem
	{
		public String label;
		public int need;
		public int approved;
		/** Submitted and awaiting review — the site's "?" state. */
		public int pending;
		/** Who sent it. Empty when nobody has, or the submission recorded no player. */
		public String player;
	}

	public static class TileGroup
	{
		public String name;
		public String logic;
		public List<TileGroupItem> items = new ArrayList<>();
	}

	public static class TileGroupItem
	{
		public String label;
		public boolean approved;
		/** Submitted and awaiting review — the site's "?" state. */
		public boolean pending;
		/** Who sent it. Empty when nobody has, or the submission recorded no player. */
		public String player;
	}
}

package com.rsbingo;

import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import javax.swing.BorderFactory;
import javax.swing.JPanel;
import net.runelite.client.ui.ColorScheme;

/**
 * One square of the board: the tile's artwork, with its tier (Showdown) or points
 * (everything else) in the bottom corner.
 *
 * Progress is carried by the border alone — graded from neutral to gold — so the
 * artwork is always drawn at full brightness and stays recognisable at 50px.
 */
class TileCell extends JPanel
{
	// Colours are read from Brand at paint time, never cached in a field. A
	// `static final Color = Brand.COMPLETED` snapshots the palette at class load, so
	// it survived even a full panel rebuild and left tile borders on the old theme
	// while everything else changed.
	private static final int RADIUS = 6;
	private static final int BAR_HEIGHT = 3;
	/** Dark enough to read as an empty track over any artwork. */
	private static final Color BAR_TRACK = new Color(0, 0, 0, 170);

	private final BoardModels.BoardTile tile;
	private final boolean showdown;

	/** Set once the artwork arrives; until then the cell paints its plain state. */
	private BufferedImage image;

	TileCell(BoardModels.BoardTile tile, BoardModels.Board board, TileImageCache images,
			 RsBingoConfig config, String siteUrl, int size, Runnable onClick)
	{
		this.tile = tile;
		this.showdown = board.isShowdown();

		setPreferredSize(new Dimension(size, size));
		setOpaque(false);
		setBackground(Brand.BG_WELL);
		setToolTipText(tooltip());

		if (tile.empty)
		{
			return;
		}

		final String url = config.showTileImages()
			? TileImageCache.resolve(siteUrl, tile.img)
			: null;
		if (url != null)
		{
			images.get(url, img ->
			{
				this.image = img;
				repaint();
			});
		}

		setCursor(new Cursor(Cursor.HAND_CURSOR));
		addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				onClick.run();
			}
		});
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		super.paintComponent(graphics);

		final Graphics2D g = (Graphics2D) graphics.create();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);

			final int w = getWidth();
			final int h = getHeight();

			// Rounded, like the site's tiles. The artwork is clipped to the same shape
			// so it can't paint over the corners.
			g.setColor(Brand.BG_WELL);
			g.fillRoundRect(0, 0, w - 1, h - 1, RADIUS, RADIUS);

			if (tile.empty)
			{
				g.setColor(Brand.BORDER.darker());
				g.drawRoundRect(0, 0, w - 1, h - 1, RADIUS, RADIUS);
				return;
			}

			g.setClip(new java.awt.geom.RoundRectangle2D.Float(0, 0, w - 1, h - 1, RADIUS, RADIUS));

			final float progress = progress();

			if (image != null)
			{
				// Contain rather than crop: tile art is often a full item sprite and
				// cropping it makes tiles hard to tell apart at 50px.
				final double scale = Math.min(w / (double) image.getWidth(), h / (double) image.getHeight());
				final int dw = Math.max(1, (int) Math.round(image.getWidth() * scale));
				final int dh = Math.max(1, (int) Math.round(image.getHeight() * scale));
				g.drawImage(image, (w - dw) / 2, (h - dh) / 2, dw, dh, null);
			}
			else
			{
				// No artwork — either still loading, unavailable, or switched off. Fall
				// back to a graded fill so the board still reads at a glance.
				g.setColor(shade(progress));
				g.fillRoundRect(0, 0, w - 1, h - 1, RADIUS, RADIUS);
			}

			drawProgressBar(g, w, h);

			g.setClip(null);
			g.setColor(borderColor());
			g.drawRoundRect(0, 0, w - 1, h - 1, RADIUS, RADIUS);

			g.setFont(getFont().deriveFont(Font.BOLD, 10f));

			// Bottom right: the tier on a Showdown board, the tile's points elsewhere.
			// The border already carries completion, so the corner is free to say what
			// the tile is worth.
			final String badge = badgeText(g);
			if (badge != null)
			{
				final int tw = g.getFontMetrics().stringWidth(badge);
				// Sits above the progress bar rather than through it.
				drawOutlined(g, badge, w - tw - 3, h - BAR_HEIGHT - 4,
					badgeIsFinished() ? Brand.COMPLETED : Color.WHITE);
			}
		}
		finally
		{
			g.dispose();
		}
	}

	/**
	 * A bar across the bottom of the cell, so you can see which tiles are nearly
	 * there without opening each one.
	 *
	 * Drawn inside the rounded clip, so it takes the cell's corners with it. The
	 * track is always painted, even at zero, so a row of tiles can be compared
	 * against a common baseline rather than by the presence of a bar.
	 */
	private void drawProgressBar(Graphics2D g, int w, int h)
	{
		final int y = h - BAR_HEIGHT - 1;

		g.setColor(BAR_TRACK);
		g.fillRect(1, y, w - 2, BAR_HEIGHT);

		final int filled = (int) Math.round((w - 2) * (barPercent() / 100.0));
		if (filled > 0)
		{
			g.setColor(barIsFull() ? Brand.COMPLETED : Brand.TEXT_MAIN);
			g.fillRect(1, y, filled, BAR_HEIGHT);
		}
	}

	/**
	 * How full the cell's bar is, 0..100.
	 *
	 * On a Showdown tile that means progress toward the *next* tier, which is what
	 * "close to completion" means there — the tier reached is already in the badge
	 * and the border. Everywhere else it is the server's collected/required.
	 */
	private double barPercent()
	{
		if (showdown && tile.hasTierProgress())
		{
			return tile.tierMaxed() ? 100 : tile.pctToNextTier();
		}
		return tile.itemsPercent();
	}

	private boolean barIsFull()
	{
		return showdown && tile.hasTierProgress() ? tile.tierMaxed() : tile.done;
	}

	/**
	 * Whether the corner badge should read as finished, in gold.
	 *
	 * On a Showdown board that means every tier is banked — *not* {@code done}, which
	 * there reports the tile's item checklist and moves independently of the tier.
	 * Colouring a tier badge by {@code done} put gold on T3 tiles whose items happened
	 * to be complete, and left genuinely maxed T5 tiles white.
	 */
	private boolean badgeIsFinished()
	{
		return showdown ? tile.tierMaxed() : tile.done;
	}

	/**
	 * What goes in the bottom-right corner, or null when nothing fits or applies.
	 *
	 * Points are written "5p" so they can't be misread as a Showdown tier, falling
	 * back to the bare number on a board packed tight enough that even that one
	 * character would overrun the cell.
	 */
	private String badgeText(Graphics2D g)
	{
		if (showdown)
		{
			return (tile.tier != null && tile.tier > 0) ? ("T" + tile.tier) : null;
		}
		if (tile.points <= 0)
		{
			return null;
		}

		final String withSuffix = tile.points + "p";
		final int room = getWidth() - 6;
		return g.getFontMetrics().stringWidth(withSuffix) <= room
			? withSuffix
			: String.valueOf(tile.points);
	}

	/** Text sits on top of artwork, so it needs its own contrast. */
	private static void drawOutlined(Graphics2D g, String text, int x, int y, Color colour)
	{
		g.setColor(Color.BLACK);
		for (int dx = -1; dx <= 1; dx++)
		{
			for (int dy = -1; dy <= 1; dy++)
			{
				if (dx != 0 || dy != 0)
				{
					g.drawString(text, x + dx, y + dy);
				}
			}
		}
		g.setColor(colour);
		g.drawString(text, x, y);
	}

	/** 0..1 — tier fraction on Showdown, done/not-done everywhere else. */
	private float progress()
	{
		if (showdown && tile.tier != null && tile.maxTier != null && tile.maxTier > 0)
		{
			return Math.max(0f, Math.min(1f, tile.tier / (float) tile.maxTier));
		}
		return tile.done ? 1f : 0f;
	}

	/** Cold-to-warm fill used when there is no artwork to draw. */
	private static Color shade(float progress)
	{
		return blend(Brand.BG_WELL, Brand.COMPLETED.darker(), progress);
	}

	private Color borderColor()
	{
		if (tile.empty)
		{
			return Brand.BORDER.darker();
		}
		final float p = progress();
		if (p >= 1f)
		{
			return Brand.COMPLETED;
		}
		if (p <= 0f)
		{
			return Brand.BORDER;
		}
		// Part-way tiles get a border between neutral and complete, so a Showdown
		// board's spread of tiers is visible without reading every badge.
		return blend(Brand.BORDER, Brand.COMPLETED, p);
	}

	private static Color blend(Color from, Color to, float amount)
	{
		final float p = Math.max(0f, Math.min(1f, amount));
		return new Color(
			(int) (from.getRed() + (to.getRed() - from.getRed()) * p),
			(int) (from.getGreen() + (to.getGreen() - from.getGreen()) * p),
			(int) (from.getBlue() + (to.getBlue() - from.getBlue()) * p));
	}

	private String tooltip()
	{
		if (tile.empty)
		{
			return null;
		}

		final StringBuilder tip = new StringBuilder("<html><b>")
			.append(Text.escape(tile.displayTitle())).append("</b>");

		if (showdown && tile.tier != null)
		{
			tip.append("<br>Tier ").append(tile.tier).append(" of ").append(tile.maxTier);
		}
		else
		{
			tip.append("<br>").append(tile.done ? "Complete" : "Not complete");
		}

		if (tile.xp == null && (tile.hasCounts() || tile.neededCount() > 0))
		{
			tip.append("<br>").append(tile.progressText()).append(" items");
		}

		return tip.append("</html>").toString();
	}
}
